import { useState } from "react";
import { Layout, Menu, Avatar, Dropdown, Typography, Badge } from "antd";
import {
  DashboardOutlined, ShoppingOutlined, CreditCardOutlined,
  RollbackOutlined, AppstoreOutlined, TagsOutlined, TeamOutlined,
  BarChartOutlined, SettingOutlined, HistoryOutlined, FlagOutlined,
  ClockCircleOutlined, MenuFoldOutlined, MenuUnfoldOutlined, LogoutOutlined, UserOutlined,
  GiftOutlined, ShopOutlined, WalletOutlined, CarOutlined, PictureOutlined, AppstoreAddOutlined,
} from "@ant-design/icons";
import { useNavigate, useLocation } from "react-router-dom";
import type { ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { useAuthStore } from "../store/auth";
import { usePermissions } from "../hooks/usePermissions";

const { Sider, Header, Content } = Layout;
const { Text } = Typography;

export function AdminShell({ children }: { children: ReactNode }) {
  const [collapsed, setCollapsed] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const staff = useAuthStore((s) => s.staff);
  const logout = useAuthStore((s) => s.logout);
  const { t } = useTranslation();
  const { canRoute } = usePermissions();

  const ALL_NAV_ITEMS = [
    { key: "/", icon: <DashboardOutlined />, label: t("nav.dashboard") },
    { key: "/orders", icon: <ShoppingOutlined />, label: t("nav.orders") },
    { key: "/transactions", icon: <CreditCardOutlined />, label: t("nav.transactions") },
    { key: "/refunds", icon: <RollbackOutlined />, label: t("nav.refunds") },
    { key: "/menu", icon: <AppstoreOutlined />, label: t("nav.menu") },
    { key: "/categories", icon: <AppstoreAddOutlined />, label: t("nav.categories", "Categories") },
    { key: "/vouchers", icon: <TagsOutlined />, label: t("nav.vouchers") },
    { key: "/bundles", icon: <GiftOutlined />, label: t("nav.bundles") },
    { key: "/stalls", icon: <ShopOutlined />, label: t("nav.stalls", "Stalls") },
    { key: "/stall-applications", icon: <ShopOutlined />, label: t("nav.stallApplications") },
    { key: "/payment-methods", icon: <WalletOutlined />, label: t("nav.paymentMethods") },
    { key: "/delivery-providers", icon: <CarOutlined />, label: t("nav.deliveryProviders") },
    { key: "/banners", icon: <PictureOutlined />, label: t("nav.banners", "Promo Banners") },
    { key: "/staff", icon: <TeamOutlined />, label: t("nav.staff") },
    { key: "/reports", icon: <BarChartOutlined />, label: t("nav.reports") },
    { key: "/activity", icon: <HistoryOutlined />, label: t("nav.activity") },
    { key: "/flags", icon: <FlagOutlined />, label: t("nav.flags") },
    { key: "/hours", icon: <ClockCircleOutlined />, label: t("nav.hours") },
    { key: "/settings", icon: <SettingOutlined />, label: t("nav.settings") },
  ];

  // Filter nav items to only those the current role can access
  const NAV_ITEMS = ALL_NAV_ITEMS.filter((item) => canRoute(item.key));

  const { i18n } = useTranslation();
  const toggleLang = () => {
    const next = i18n.language === "zh" ? "en" : "zh";
    void i18n.changeLanguage(next);
    localStorage.setItem("kawkaw_admin_lang", next);
  };

  const userMenu = {
    items: [
      {
        key: "lang",
        icon: <span style={{ fontSize: 14 }}>🌐</span>,
        label: i18n.language === "zh" ? "English" : "中文",
        onClick: toggleLang,
      },
      {
        key: "logout",
        icon: <LogoutOutlined />,
        label: t("common.signOut"),
        danger: true,
        onClick: () => { logout(); void navigate("/login"); },
      },
    ],
  };

  return (
    <Layout style={{ minHeight: "100vh" }}>
      <Sider
        collapsible
        collapsed={collapsed}
        trigger={null}
        width={220}
        collapsedWidth={64}
        theme="dark"
        style={{ position: "fixed", insetBlockStart: 0, insetInlineStart: 0, height: "100vh", overflow: "auto", zIndex: 100 }}
      >
        {/* Logo */}
        <div style={{
          height: 64, display: "flex", alignItems: "center", justifyContent: collapsed ? "center" : "flex-start",
          padding: collapsed ? 0 : "0 20px", borderBottom: "1px solid #374151",
        }}>
          {collapsed ? (
            <span style={{ fontSize: 22 }}>☕</span>
          ) : (
            <Text style={{ color: "#D97706", fontWeight: 700, fontSize: 16 }}>KawKaw Admin</Text>
          )}
        </div>

        <Menu
          theme="dark"
          mode="inline"
          selectedKeys={[location.pathname]}
          items={NAV_ITEMS}
          onClick={({ key }) => void navigate(key)}
          style={{ flex: 1, borderRight: 0 }}
        />
      </Sider>

      <Layout style={{ marginInlineStart: collapsed ? 64 : 220, transition: "margin 0.2s" }}>
        <Header style={{
          position: "sticky", top: 0, zIndex: 99,
          background: "#fff", padding: "0 24px",
          display: "flex", alignItems: "center", justifyContent: "space-between",
          borderBottom: "1px solid #E5E7EB", height: 64,
          boxShadow: "0 1px 4px rgba(0,0,0,0.06)",
        }}>
          <button
            onClick={() => setCollapsed(!collapsed)}
            style={{ background: "none", border: "none", cursor: "pointer", fontSize: 18, color: "#374151", padding: 4 }}
          >
            {collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
          </button>

          <Dropdown menu={userMenu} placement="bottomRight" arrow>
            <div style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer" }}>
              <Badge dot color="#10B981" offset={[-2, 2]}>
                <Avatar icon={<UserOutlined />} size={34} style={{ background: "#D97706" }} />
              </Badge>
              {!collapsed && (
                <div style={{ lineHeight: 1.3 }}>
                  <Text strong style={{ fontSize: 13, display: "block" }}>{staff?.name ?? "Admin"}</Text>
                  <Text style={{ fontSize: 11, color: "#6B7280", textTransform: "capitalize" }}>{staff?.role ?? ""}</Text>
                </div>
              )}
            </div>
          </Dropdown>
        </Header>

        <Content style={{ padding: 24, minHeight: "calc(100vh - 64px)" }}>
          {children}
        </Content>
      </Layout>
    </Layout>
  );
}
