import { useState } from "react";
import { Input, Select, DatePicker, Space, Typography, Tag } from "antd";
import { SearchOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { ActivityLog } from "@kawkaw/shared";
import dayjs from "dayjs";
import { DataTable } from "../components/DataTable";
import { AdminShell } from "../layouts/AdminShell";
import { useActivityLog } from "../api/hooks";

const { Title, Text } = Typography;
const { RangePicker } = DatePicker;

const ACTION_COLOR: Record<string, string> = {
  create: "success",
  update: "processing",
  delete: "error",
  login: "blue",
  logout: "default",
  refund: "orange",
  reset_pin: "warning",
};

export function ActivityLogScreen() {
  const { t } = useTranslation();
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [action, setAction] = useState<string | undefined>();
  const [dateRange, setDateRange] = useState<[string, string] | null>(null);

  const { data, isLoading } = useActivityLog({
    page, limit: 20,
    q: search || undefined,
    action,
    from: dateRange?.[0],
    to: dateRange?.[1],
  });

  const columns: ColumnsType<ActivityLog> = [
    {
      title: t("activity.colStaff"), key: "staff", width: 160,
      render: (_, row) => {
        const r = row as unknown as { staff?: { name: string } };
        return r.staff?.name ?? "System";
      },
    },
    {
      title: t("activity.colAction"), dataIndex: "action", key: "action", width: 100,
      render: (v: string) => <Tag color={ACTION_COLOR[v] ?? "default"}>{v}</Tag>,
    },
    {
      title: t("activity.colEntity"), key: "entity", width: 160,
      render: (_, row) => {
        const r = row as unknown as { entity_type?: string; entity_id?: string };
        return r.entity_type
          ? <Text style={{ fontSize: 12 }}>{r.entity_type} <Text code style={{ fontSize: 11 }}>{r.entity_id?.slice(-8)}</Text></Text>
          : "—";
      },
    },
    {
      title: t("activity.colDetails"), dataIndex: "meta", key: "desc",
      render: (v: Record<string, unknown> | null) => v && Object.keys(v).length > 0
        ? <Text style={{ fontSize: 12, color: "#374151", fontFamily: "monospace" }}>{JSON.stringify(v)}</Text>
        : "—",
    },
    {
      title: t("activity.colIp"), dataIndex: "ip", key: "ip", width: 130,
      render: (v: string | null) => v ? <Text code style={{ fontSize: 11 }}>{v}</Text> : "—",
    },
    {
      title: t("activity.colTime"), dataIndex: "created_at", key: "time", width: 155,
      render: (v: string) => dayjs(v).format("DD MMM YYYY HH:mm:ss"),
      sorter: true,
    },
  ];

  return (
    <AdminShell>
      <Title level={4} style={{ marginBottom: 16 }}>{t("activity.title")}</Title>

      <Space wrap style={{ marginBottom: 16 }}>
        <Input prefix={<SearchOutlined />} placeholder={t("activity.searchPlaceholder")}
          value={search} onChange={(e) => setSearch(e.target.value)} style={{ width: 240 }} allowClear />
        <Select placeholder={t("activity.filterAction")} allowClear value={action} onChange={setAction} style={{ width: 140 }}
          options={["create", "update", "delete", "login", "logout", "refund", "reset_pin"]
            .map((a) => ({ value: a, label: a }))} />
        <RangePicker showTime onChange={(_, s) => setDateRange(s[0] && s[1] ? [s[0], s[1]] : null)} />
      </Space>

      <DataTable<ActivityLog>
        columns={columns}
        dataSource={data?.data ?? []}
        loading={isLoading}
        pagination={{ current: page, total: data?.meta.total ?? 0, pageSize: 20, onChange: (p) => setPage(p) }}
      />
    </AdminShell>
  );
}
