import { useState } from "react";
import {
  Button, Modal, Form, Input, Select, Switch, Space, Typography, Tag,
  Popconfirm, message, Tooltip, Table, Badge,
} from "antd";
import {
  PlusOutlined, EditOutlined, DeleteOutlined, ApiOutlined, WalletOutlined,
} from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { PaymentMethodConfig } from "@kawkaw/shared";
import { AdminShell } from "../layouts/AdminShell";
import {
  usePaymentMethodConfigs, useCreatePaymentMethodConfig,
  useUpdatePaymentMethodConfig, useDeletePaymentMethodConfig, useTestPaymentMethodConfig,
} from "../api/hooks";

const { Title, Text } = Typography;

const PROVIDERS = [
  { value: "billplz", label: "Billplz (FPX/Cards)" },
  { value: "toyyibpay", label: "ToyyibPay" },
  { value: "stripe", label: "Stripe" },
  { value: "manual", label: "Manual / Cash" },
  { value: "qr_static", label: "Static QR Code" },
  { value: "grabpay", label: "GrabPay Direct" },
  { value: "boost", label: "Boost" },
  { value: "tng", label: "Touch 'n Go eWallet" },
  { value: "custom", label: "Custom Provider" },
];

const METHODS = [
  { value: "fpx", label: "FPX" },
  { value: "visa", label: "Visa / MasterCard" },
  { value: "grabpay", label: "GrabPay" },
  { value: "cash", label: "Cash" },
  { value: "ewallet", label: "eWallet" },
  { value: "tng", label: "Touch 'n Go" },
  { value: "boost", label: "Boost" },
  { value: "qr", label: "QR Code (Static)" },
];

const PROVIDER_COLOR: Record<string, string> = {
  billplz: "blue", toyyibpay: "green", stripe: "purple",
  manual: "default", qr_static: "orange", grabpay: "cyan",
  boost: "lime", tng: "gold", custom: "geekblue",
};

export function PaymentMethodsScreen() {
  const { t } = useTranslation();
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<PaymentMethodConfig | null>(null);
  const [form] = Form.useForm();

  const { data, isLoading } = usePaymentMethodConfigs();
  const createConfig = useCreatePaymentMethodConfig();
  const updateConfig = useUpdatePaymentMethodConfig();
  const deleteConfig = useDeletePaymentMethodConfig();
  const testConfig = useTestPaymentMethodConfig();

  const openCreate = () => { setEditing(null); form.resetFields(); setModalOpen(true); };
  const openEdit = (row: PaymentMethodConfig) => {
    setEditing(row);
    form.setFieldsValue({ ...row });
    setModalOpen(true);
  };

  const onSave = async (values: Record<string, unknown>) => {
    try {
      if (editing) {
        await updateConfig.mutateAsync({ id: editing.id, ...values });
        void message.success(t("paymentMethods.updateSuccess"));
      } else {
        await createConfig.mutateAsync(values);
        void message.success(t("paymentMethods.createSuccess"));
      }
      setModalOpen(false);
    } catch { void message.error(t("paymentMethods.saveFailed")); }
  };

  const onDelete = async (id: string) => {
    try { await deleteConfig.mutateAsync(id); void message.success(t("paymentMethods.deleteSuccess")); }
    catch { void message.error(t("paymentMethods.deleteFailed")); }
  };

  const onTest = async (id: string) => {
    try {
      const res = await testConfig.mutateAsync(id);
      const result = (res as { data?: { success: boolean; message: string } }).data;
      if (result?.success) void message.success(`✅ ${result.message}`);
      else void message.error(`❌ ${result?.message ?? "Test failed"}`);
    } catch { void message.error(t("paymentMethods.testFailed")); }
  };

  const items = (data as { data?: PaymentMethodConfig[] } | undefined)?.data ?? [];

  const columns: ColumnsType<PaymentMethodConfig> = [
    {
      title: t("paymentMethods.colProvider"), dataIndex: "provider", key: "provider", width: 160,
      render: (v: string) => <Tag color={PROVIDER_COLOR[v] ?? "default"}>{PROVIDERS.find(p => p.value === v)?.label ?? v}</Tag>,
    },
    {
      title: t("paymentMethods.colMethod"), dataIndex: "method", key: "method", width: 130,
      render: (v: string) => <Tag>{METHODS.find(m => m.value === v)?.label ?? v}</Tag>,
    },
    {
      title: t("paymentMethods.colDisplayName"), dataIndex: "display_name", key: "display_name",
      render: (v: string) => <Text strong>{v}</Text>,
    },
    {
      title: t("paymentMethods.colApiKey"), dataIndex: "api_key", key: "api_key", width: 160,
      render: (v: string | null) => v ? <Text code style={{ fontSize: 11 }}>{v}</Text> : <Text type="secondary">—</Text>,
    },
    {
      title: t("paymentMethods.colQrCode"), dataIndex: "qr_image_url", key: "qr", width: 80,
      render: (v: string | null) => v ? (
        <Tooltip title={<img src={v} alt="QR" style={{ width: 120, height: 120 }} />}>
          <Badge status="success" text="QR" />
        </Tooltip>
      ) : <Text type="secondary">—</Text>,
    },
    {
      title: t("paymentMethods.colStatus"), dataIndex: "is_active", key: "active", width: 90,
      render: (v: boolean) => <Tag color={v ? "success" : "default"}>{v ? t("common.yes") : t("common.no")}</Tag>,
    },
    {
      title: "", key: "actions", width: 140, fixed: "right" as const,
      render: (_: unknown, row: PaymentMethodConfig) => (
        <Space>
          <Tooltip title={t("paymentMethods.testConnection")}>
            <Button size="small" icon={<ApiOutlined />} loading={testConfig.isPending} onClick={() => void onTest(row.id)} />
          </Tooltip>
          <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(row)} />
          <Popconfirm title={t("paymentMethods.confirmDelete")} onConfirm={() => void onDelete(row.id)} okType="danger" placement="left">
            <Button size="small" danger icon={<DeleteOutlined />} />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <AdminShell>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <div>
          <Title level={4} style={{ margin: 0 }}>{t("paymentMethods.title")}</Title>
          <Text type="secondary" style={{ fontSize: 12 }}>{t("paymentMethods.subtitle")}</Text>
        </div>
        <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}
          style={{ background: "#D97706", borderColor: "#D97706" }}>
          {t("paymentMethods.addMethod")}
        </Button>
      </div>

      <Table<PaymentMethodConfig>
        columns={columns}
        dataSource={items}
        rowKey="id"
        loading={isLoading}
        size="middle"
        pagination={{ pageSize: 20 }}
        scroll={{ x: 900 }}
      />

      <Modal
        open={modalOpen}
        title={
          <Space>
            <WalletOutlined />
            {editing ? t("paymentMethods.editTitle") : t("paymentMethods.newTitle")}
          </Space>
        }
        onCancel={() => setModalOpen(false)}
        onOk={() => void form.submit()}
        okText={t("common.save")}
        okButtonProps={{ style: { background: "#D97706", borderColor: "#D97706" }, loading: createConfig.isPending || updateConfig.isPending }}
        width={580}
        maskClosable={false}
      >
        <Form form={form} layout="vertical" onFinish={onSave}>
          <Space style={{ width: "100%" }} size={12}>
            <Form.Item name="provider" label={t("paymentMethods.formProvider")} rules={[{ required: true }]} style={{ flex: 1 }}>
              <Select options={PROVIDERS} placeholder="Select provider" />
            </Form.Item>
            <Form.Item name="method" label={t("paymentMethods.formMethod")} rules={[{ required: true }]} style={{ flex: 1 }}>
              <Select options={METHODS} placeholder="Select method" />
            </Form.Item>
          </Space>
          <Form.Item name="display_name" label={t("paymentMethods.formDisplayName")} rules={[{ required: true }]}>
            <Input placeholder="e.g. Billplz FPX, Cash Payment" />
          </Form.Item>
          <Form.Item name="api_key" label={t("paymentMethods.formApiKey")}>
            <Input.Password placeholder={t("paymentMethods.formApiKeyPlaceholder")} visibilityToggle />
          </Form.Item>
          <Form.Item name="api_secret" label={t("paymentMethods.formApiSecret")}>
            <Input.Password placeholder={t("paymentMethods.formApiSecretPlaceholder")} visibilityToggle />
          </Form.Item>
          <Form.Item name="collection_id" label={t("paymentMethods.formCollectionId")}>
            <Input placeholder="e.g. Billplz Collection ID" />
          </Form.Item>
          <Form.Item name="webhook_secret" label={t("paymentMethods.formWebhookSecret")}>
            <Input.Password placeholder={t("paymentMethods.formWebhookSecretPlaceholder")} visibilityToggle />
          </Form.Item>
          <Form.Item name="qr_image_url" label={t("paymentMethods.formQrImageUrl")}>
            <Input placeholder="https://... (URL to QR code image)" />
          </Form.Item>
          <Space style={{ width: "100%" }} size={12}>
            <Form.Item name="sort_order" label={t("paymentMethods.formSortOrder")} initialValue={0} style={{ flex: 1 }}>
              <Input type="number" min={0} />
            </Form.Item>
            <Form.Item name="is_active" label={t("paymentMethods.formIsActive")} valuePropName="checked" initialValue={true} style={{ flex: 1 }}>
              <Switch checkedChildren={t("common.yes")} unCheckedChildren={t("common.no")} />
            </Form.Item>
          </Space>
        </Form>
      </Modal>
    </AdminShell>
  );
}
