import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { getClient } from "./client";
import type {
  Order, Transaction, MenuItem, Stall, Staff,
  Voucher, Bundle, ActivityLog, StallApplication, PaymentMethodConfig, DeliveryProvider, PromoBanner,
} from "@kawkaw/shared";

const api = () => getClient();

// Generic helper: backend returns { code, msg, data: T } via reply.ok()
type ApiOk<T> = { code: number; msg: string; data: T };
// Paginated backend shape: reply.ok({ items, page, total })
type PagedOk<T> = ApiOk<{ items: T[]; page: number; total: number }>;

/* ── Auth ── */
export function useAdminLogin() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: { email: string; password: string }) =>
      api().post("auth/admin/login", { json: body }).json<{
        data: { admin: { id: string; name: string; role: string; kopitiam_id: string }; tokens: { accessToken: string; refreshToken: string } };
      }>(),
    onSuccess: () => qc.clear(),
  });
}

