/* ── Orders ── */
export function useAdminOrders(params: Record<string, string | number | undefined>) {
  return useQuery({
    queryKey: ["admin", "orders", params],
    queryFn: async () => {
      const sp = new URLSearchParams();
      for (const [k, v] of Object.entries(params)) { if (v != null) sp.set(k, String(v)); }
      const res = await api().get(`admin/orders?${sp}`).json<PagedOk<Order>>();
      return {
        data: res.data.items ?? [],
        meta: { total: res.data.total, page: res.data.page, limit: Number(params.limit ?? 20) },
      };
    },
  });
}

