/* ── Vouchers ── */
export function useAdminVouchers() {
  return useQuery({
    queryKey: ["admin", "vouchers"],
    queryFn: async () => {
      type RawVoucher = { id: string; code: string; name: string; type: string; value: string; min_order: string; total_uses: number | null; used_count: number; status: string; valid_from: string; valid_to: string };
      const res = await api().get("admin/vouchers").json<ApiOk<RawVoucher[]>>();
      return {
        ...res,
        data: res.data.map((v) => ({
          ...v,
          discount_type: v.type,
          discount_value: v.value,
          min_spend: v.min_order,
          usage_limit: v.total_uses,
          valid_until: v.valid_to,
        })),
      };
    },
  });
}

export function useCreateVoucher() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: Record<string, unknown>) => {
      // Map screen field names → backend field names
      const payload: Record<string, unknown> = { ...body };
      if ("discount_type" in payload) { payload.type = payload.discount_type; delete payload.discount_type; }
      if ("discount_value" in payload) { payload.value = Number(payload.discount_value); delete payload.discount_value; }
      if ("min_spend" in payload) { payload.min_order = Number(payload.min_spend ?? 0); delete payload.min_spend; }
      if ("usage_limit" in payload) { payload.total_uses = payload.usage_limit; delete payload.usage_limit; }
      if ("valid_until" in payload) { payload.valid_to = payload.valid_until; delete payload.valid_until; }
      // Remove screen-only fields
      delete payload.is_single_use;
      return api().post("admin/vouchers", { json: payload }).json();
    },
    onSuccess: () => { void qc.invalidateQueries({ queryKey: ["admin", "vouchers"] }); },
  });
}

export function useUpdateVoucher() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, ...body }: Record<string, unknown> & { id: string }) => {
      // Map screen field names → backend field names
      const payload: Record<string, unknown> = { ...body };
      if ("discount_type" in payload) { payload.type = payload.discount_type; delete payload.discount_type; }
      if ("discount_value" in payload) { payload.value = Number(payload.discount_value); delete payload.discount_value; }
      if ("min_spend" in payload) { payload.min_order = Number(payload.min_spend ?? 0); delete payload.min_spend; }
      if ("usage_limit" in payload) { payload.total_uses = payload.usage_limit; delete payload.usage_limit; }
      if ("valid_until" in payload) { payload.valid_to = payload.valid_until; delete payload.valid_until; }
      delete payload.is_single_use;
      return api().patch(`admin/vouchers/${id}`, { json: payload }).json();
    },
    onSuccess: () => { void qc.invalidateQueries({ queryKey: ["admin", "vouchers"] }); },
  });
}

