/* ── Hours & Holidays ── */
export function useKopitiamHours() {
  return useQuery({
    queryKey: ["admin", "hours"],
    queryFn: async () => {
      const res = await api().get("admin/hours").json<ApiOk<{ day_of_week: number; opens_at: string; closes_at: string }[]>>();
      return {
        ...res,
        data: res.data.map((r) => {
          const isClosed = r.opens_at === "00:00" && r.closes_at === "00:00";
          return {
            dayOfWeek: r.day_of_week,
            openTime: isClosed ? "08:00" : r.opens_at,
            closeTime: isClosed ? "22:00" : r.closes_at,
            isClosed,
          };
        }),
      };
    },
  });
}

export function useUpdateHours() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: { dayOfWeek: number; openTime: string; closeTime: string; isClosed: boolean }[]) =>
      api().patch("admin/hours", {
        json: {
          entries: body.map((h) => ({
            day_of_week: h.dayOfWeek,
            opens_at: h.isClosed ? "00:00" : h.openTime,
            closes_at: h.isClosed ? "00:00" : h.closeTime,
          })),
        },
      }).json(),
    onSuccess: () => { void qc.invalidateQueries({ queryKey: ["admin", "hours"] }); },
  });
}

