import { Form, Input, Button, Card, Typography, App } from "antd";
import { UserOutlined, LockOutlined } from "@ant-design/icons";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { useAdminLogin } from "../api/hooks";
import { useAuthStore } from "../store/auth";

const { Title, Text } = Typography;

interface LoginForm { email: string; password: string }

export function LoginScreen() {
  const navigate = useNavigate();
  const login = useAdminLogin();
  const { setTokens, setStaff } = useAuthStore();
  const { t } = useTranslation();
  const [form] = Form.useForm<LoginForm>();
  const { message } = App.useApp();

  const onFinish = async (values: LoginForm) => {
    try {
      const res = await login.mutateAsync(values);
      setTokens(res.data.tokens.accessToken, res.data.tokens.refreshToken);
      setStaff({
        id: res.data.admin.id,
        name: res.data.admin.name,
        role: res.data.admin.role,
        kopitiamId: res.data.admin.kopitiam_id,
      });
      void navigate("/");
    } catch {
      void message.error(t("auth.loginFailed"));
    }
  };

  return (
    <div style={{
      minHeight: "100vh", background: "linear-gradient(135deg, #111827 0%, #1F2937 100%)",
      display: "flex", alignItems: "center", justifyContent: "center",
    }}>
      <Card style={{ width: 400, borderRadius: 16, boxShadow: "0 20px 60px rgba(0,0,0,0.4)" }}>
        <div style={{ textAlign: "center", marginBottom: 32 }}>
          <div style={{ fontSize: 48, marginBottom: 8 }}>☕</div>
          <Title level={3} style={{ margin: 0, color: "#D97706" }}>KawKaw Kopitiam</Title>
          <Text type="secondary" style={{ fontSize: 13 }}>{t("auth.login")}</Text>
        </div>

        <Form form={form} layout="vertical" onFinish={onFinish} autoComplete="off">
          <Form.Item name="email" label={t("auth.email")} rules={[{ required: true }, { type: "email" }]}>
            <Input prefix={<UserOutlined />} placeholder="admin@kawkaw.my" size="large" />
          </Form.Item>
          <Form.Item name="password" label={t("auth.password")} rules={[{ required: true }]}>
            <Input.Password prefix={<LockOutlined />} placeholder={t("auth.password")} size="large" />
          </Form.Item>
          <Form.Item style={{ marginBottom: 0 }}>
            <Button
              type="primary"
              htmlType="submit"
              loading={login.isPending}
              size="large"
              block
              style={{ background: "#D97706", borderColor: "#D97706" }}
            >
              {t("auth.loginBtn")}
            </Button>
          </Form.Item>
        </Form>

        {import.meta.env.DEV && (
          <div style={{ marginTop: 16, padding: 10, background: "#FEF3C7", borderRadius: 8, fontSize: 12, color: "#92400E", lineHeight: 1.6 }}>
            <strong>Demo:</strong><br />
            <b>admin@kawkaw.my</b> / <b>Admin@Kawkaw1</b> (superadmin)<br />
            <b>admin2@kawkaw.my</b> / <b>Admin@Kawkaw2</b> (admin)
          </div>
        )}
      </Card>
    </div>
  );
}
