import { useState } from "react";
import {
  Button, Modal, Form, Input, InputNumber, Switch,
  DatePicker, Select, Typography, Space, Popconfirm, message, Tag, Table,
} from "antd";
import { PlusOutlined, EditOutlined, DeleteOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { Bundle } from "@kawkaw/shared";
import dayjs from "dayjs";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminBundles, useAdminMenuItems, useAdminStalls, useAdminMenuCategories, useCreateBundle, useUpdateBundle, useDeleteBundle } from "../api/hooks";

const { Title, Text } = Typography;
const { RangePicker } = DatePicker;

export function BundlesScreen() {
  const { t } = useTranslation();
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Bundle | null>(null);
  const [form] = Form.useForm();

  const { data: bundlesData, isLoading } = useAdminBundles();
  const { data: stallsData } = useAdminStalls();
  const { data: catData } = useAdminMenuCategories();
  const categoryOptions = (catData?.data ?? []).map((c: { id: string; name: string; emoji?: string | null }) => ({
    value: c.id,
    label: `${c.emoji ?? ""} ${c.name}`.trim(),
  }));
  const [selectedStall, setSelectedStall] = useState<string | undefined>();
  const { data: menuData } = useAdminMenuItems(selectedStall);
  const createBundle = useCreateBundle();
  const updateBundle = useUpdateBundle();
  const deleteBundle = useDeleteBundle();

  // menuData is used indirectly via selectedStall to populate stall items context
  void menuData;

  const openCreate = () => { setEditing(null); form.resetFields(); setModalOpen(true); };
  const openEdit = (b: Bundle) => {
    setEditing(b);
    form.setFieldsValue({
      ...b,
      valid_range: [dayjs(b.valid_from), dayjs(b.valid_to)],
      original_price: Number(b.original_price),
      bundle_price: Number(b.bundle_price),
      items: b.items ? JSON.stringify(b.items) : "[]",
      category_ids: b.category_ids ?? [],
    });
    setModalOpen(true);
  };

  const onSave = async (values: Record<string, unknown>) => {
    try {
      const { valid_range, ...rest } = values as { valid_range: [dayjs.Dayjs, dayjs.Dayjs]; [k: string]: unknown };
      let parsedItems: unknown = rest.items;
      if (typeof rest.items === "string") {
        try { parsedItems = JSON.parse(rest.items || "[]"); } catch { parsedItems = []; }
      }
      const payload = {
        ...rest,
        items: parsedItems,
        valid_from: valid_range[0].toISOString(),
        valid_to: valid_range[1].toISOString(),
      };
      if (editing) {
        await updateBundle.mutateAsync({ id: editing.id, ...payload } as Bundle & { id: string });
        void message.success(t("bundles.updateSuccess"));
      } else {
        await createBundle.mutateAsync(payload as Partial<Bundle>);
        void message.success(t("bundles.createSuccess"));
      }
      setModalOpen(false);
    } catch { void message.error(t("bundles.saveFailed")); }
  };

  const onDelete = async (id: string) => {
    try { await deleteBundle.mutateAsync(id); void message.success(t("bundles.deleteSuccess")); }
    catch { void message.error(t("bundles.deleteFailed")); }
  };

  const catMap = new Map((catData?.data ?? []).map((c) => [c.id, c]));

  const columns: ColumnsType<Bundle> = [
    { title: t("bundles.colName"), dataIndex: "name", key: "name", render: (v: string) => <Text strong>{v}</Text> },
    { title: t("bundles.colBundlePrice"), dataIndex: "bundle_price", key: "bundle_price", width: 120, render: (v: string) => <b style={{ color: "#D97706" }}>RM {Number(v).toFixed(2)}</b> },
    { title: t("bundles.colOriginalPrice"), dataIndex: "original_price", key: "original_price", width: 120, render: (v: string) => <Text delete type="secondary">RM {Number(v).toFixed(2)}</Text> },
    {
      title: t("menu.categories", "Categories"), dataIndex: "category_ids", key: "category_ids",
      render: (ids: string[]) => ids?.length
        ? ids.map((id) => { const c = catMap.get(id); return c ? <Tag key={id}>{c.emoji} {c.name}</Tag> : null; })
        : <Text type="secondary">—</Text>,
    },
    {
      title: t("bundles.colFor"), dataIndex: "applicable_for", key: "for", width: 100,
      render: (v: string) => <Tag>{v}</Tag>,
    },
    {
      title: t("bundles.colValid"), key: "valid", width: 200,
      render: (_, row) => <Text style={{ fontSize: 12 }}>{dayjs(row.valid_from).format("D MMM")} – {dayjs(row.valid_to).format("D MMM YYYY")}</Text>,
    },
    {
      title: t("bundles.colActive"), dataIndex: "is_active", key: "active", width: 80,
      render: (v: boolean) => <Tag color={v ? "success" : "default"}>{v ? t("common.yes") : t("common.no")}</Tag>,
    },
    {
      title: "", key: "actions", width: 100, fixed: "right" as const,
      render: (_: unknown, row: Bundle) => (
        <Space>
          <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(row)} />
          <Popconfirm title={t("bundles.confirmDelete")} onConfirm={() => void onDelete(row.id)} okType="danger" placement="left">
            <Button size="small" danger icon={<DeleteOutlined />} />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <AdminShell>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <Title level={4} style={{ margin: 0 }}>{t("bundles.title")}</Title>
        <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}
          style={{ background: "#D97706", borderColor: "#D97706" }}>
          {t("bundles.newBundle")}
        </Button>
      </div>

      <Table<Bundle>
        columns={columns}
        dataSource={bundlesData?.data ?? []}
        rowKey="id"
        loading={isLoading}
        size="middle"
        pagination={{ pageSize: 20 }}
      />

      <Modal
        open={modalOpen}
        title={editing ? t("bundles.editTitle") : t("bundles.newTitle")}
        onCancel={() => setModalOpen(false)}
        onOk={() => void form.submit()}
        okText={t("common.save")}
        okButtonProps={{ style: { background: "#D97706", borderColor: "#D97706" }, loading: createBundle.isPending || updateBundle.isPending }}
        width={620}
        maskClosable={false}
      >
        <Form form={form} layout="vertical" onFinish={onSave}>
          <Form.Item name="name" label={t("bundles.formName")} rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="description" label={t("bundles.formDescription")}>
            <Input.TextArea rows={2} />
          </Form.Item>
          <Form.Item name="category_ids" label={t("menu.categories", "Categories")}>
            <Select
              mode="multiple"
              allowClear
              options={categoryOptions}
              placeholder={t("menu.categorySelectPlaceholder", "Select categories (optional)")}
            />
          </Form.Item>
          <Form.Item label={t("bundles.formItemsLabel")}>
            <Space.Compact style={{ width: "100%" }}>
              <Select placeholder={t("bundles.formStall")} value={selectedStall} onChange={setSelectedStall} style={{ width: 160 }}
                options={(stallsData?.data ?? []).map((s: { id: string; name: string }) => ({ value: s.id, label: s.name }))} />
            </Space.Compact>
          </Form.Item>
          <Form.Item name="items" label={t("bundles.formItemsJson")} initialValue={[]}>
            <Input.TextArea rows={3} placeholder='[{"menu_item_id":"...","qty":1}]' />
          </Form.Item>
          <Space style={{ width: "100%" }} size={12}>
            <Form.Item name="original_price" label={t("bundles.formOriginalPrice")} rules={[{ required: true }]} style={{ flex: 1 }}>
              <InputNumber prefix="RM" min={0} precision={2} style={{ width: "100%" }} />
            </Form.Item>
            <Form.Item name="bundle_price" label={t("bundles.formBundlePrice")} rules={[{ required: true }]} style={{ flex: 1 }}>
              <InputNumber prefix="RM" min={0} precision={2} style={{ width: "100%" }} />
            </Form.Item>
          </Space>
          <Form.Item name="applicable_for" label={t("bundles.formApplicableFor")} initialValue="both">
            <Select options={[
              { value: "both", label: t("bundles.formApplicableBoth") },
              { value: "pickup", label: t("bundles.formApplicablePickup") },
              { value: "delivery", label: t("bundles.formApplicableDelivery") },
            ]} />
          </Form.Item>
          <Form.Item name="valid_range" label={t("bundles.formValidityPeriod")} rules={[{ required: true }]}>
            <RangePicker showTime style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="is_active" label={t("bundles.formIsActive")} valuePropName="checked" initialValue={true}>
            <Switch checkedChildren={t("common.yes")} unCheckedChildren={t("common.no")} />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
