import { Tag } from "antd";

const COLOR_MAP: Record<string, string> = {
  // Order statuses
  pending: "default",
  confirmed: "processing",
  preparing: "warning",
  ready: "cyan",
  out_for_delivery: "blue",
  in_transit: "geekblue",
  delivered: "success",
  completed: "success",
  cancelled: "error",
  // Payment / refund statuses
  paid: "success",
  unpaid: "default",
  refunded: "purple",
  partially_refunded: "volcano",
  approved: "success",
  rejected: "error",
  pending_review: "warning",
  // Staff / misc
  active: "success",
  inactive: "default",
  open: "success",
  closed: "error",
};

export function StatusTag({ status }: { status: string }) {
  const color = COLOR_MAP[status] ?? "default";
  return <Tag color={color} style={{ textTransform: "capitalize" }}>{status.replace(/_/g, " ")}</Tag>;
}
