import { Row, Col, Card, Statistic, Spin, Typography, Tag, Progress } from "antd";
import {
  DollarOutlined, ShoppingOutlined, RollbackOutlined, TeamOutlined, FireOutlined,
} from "@ant-design/icons";
import { useDashboardStats, useAdminDailyReport } from "../api/hooks";
import { AdminShell } from "../layouts/AdminShell";
import { useTranslation } from "react-i18next";

const { Title } = Typography;

function StatCard({ title, value, prefix, color }: { title: string; value: string | number; prefix: React.ReactNode; color: string }) {
  return (
    <Card style={{ borderRadius: 12, borderTop: `4px solid ${color}` }}>
      <Statistic
        title={<span style={{ fontSize: 13, color: "#6B7280" }}>{title}</span>}
        value={value}
        prefix={<span style={{ color }}>{prefix}</span>}
        valueStyle={{ fontSize: 28, fontWeight: 700, color: "#111827" }}
      />
    </Card>
  );
}

export function DashboardScreen() {
  const { data, isLoading } = useDashboardStats();
  const stats = data?.data;
  const { data: dailyData, isLoading: dailyLoading } = useAdminDailyReport();
  const daily = dailyData?.data;
  const { t } = useTranslation();

  const kitchenPct = daily ? Math.min(100, Math.round((daily.kitchenLoad.active / daily.kitchenLoad.capacity) * 100)) : 0;

  return (
    <AdminShell>
      <Title level={4} style={{ marginBottom: 24 }}>{t("nav.dashboard")}</Title>
      {isLoading ? (
        <div style={{ textAlign: "center", padding: 60 }}><Spin size="large" /></div>
      ) : (
        <>
          <Row gutter={[16, 16]}>
            <Col xs={24} sm={12} lg={6}>
              <StatCard title={t("dashboard.todayRevenue")} value={`RM ${stats?.todayRevenue ?? "0.00"}`} prefix={<DollarOutlined />} color="#D97706" />
            </Col>
            <Col xs={24} sm={12} lg={6}>
              <StatCard title={t("dashboard.todayOrders")} value={stats?.todayOrders ?? 0} prefix={<ShoppingOutlined />} color="#3B82F6" />
            </Col>
            <Col xs={24} sm={12} lg={6}>
              <StatCard title={t("dashboard.pendingRefunds")} value={stats?.pendingRefunds ?? 0} prefix={<RollbackOutlined />} color="#EF4444" />
            </Col>
            <Col xs={24} sm={12} lg={6}>
              <StatCard title={t("dashboard.activeStaff")} value={stats?.activeStaff ?? 0} prefix={<TeamOutlined />} color="#10B981" />
            </Col>
          </Row>

          <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
            <Col xs={24} lg={12}>
              <Card title={t("dashboard.kitchenLoad", "Kitchen load")} style={{ borderRadius: 12 }} loading={dailyLoading}>
                <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
                  <FireOutlined style={{ fontSize: 28, color: kitchenPct > 80 ? "#EF4444" : kitchenPct > 50 ? "#F59E0B" : "#10B981" }} />
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 13, color: "#6B7280", marginBottom: 6 }}>
                      {daily ? `${daily.kitchenLoad.active} / ${daily.kitchenLoad.capacity} ${t("dashboard.activeOrders", "active orders")}` : "—"}
                    </div>
                    <Progress percent={kitchenPct} strokeColor={kitchenPct > 80 ? "#EF4444" : kitchenPct > 50 ? "#F59E0B" : "#10B981"} showInfo={false} />
                  </div>
                </div>
                <div style={{ marginTop: 16, fontSize: 13 }}>
                  <span style={{ color: "#6B7280" }}>{t("dashboard.avgTicket", "Average ticket")}: </span>
                  <strong>RM {daily?.avgTicketSize ?? "0.00"}</strong>
                </div>
              </Card>
            </Col>
            <Col xs={24} lg={12}>
              <Card title={t("dashboard.orderBreakdown", "Order breakdown")} style={{ borderRadius: 12 }} loading={dailyLoading}>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {Object.entries(daily?.ordersByStatus ?? {}).length === 0 && (
                    <span style={{ color: "#9CA3AF", fontSize: 13 }}>{t("dashboard.noOrdersYet", "No orders yet today")}</span>
                  )}
                  {Object.entries(daily?.ordersByStatus ?? {}).map(([status, count]) => (
                    <Tag key={status} style={{ padding: "4px 10px", fontSize: 13 }}>
                      {status.replace(/_/g, " ")}: <strong>{count}</strong>
                    </Tag>
                  ))}
                </div>
              </Card>
            </Col>
          </Row>

          <Row gutter={[16, 16]} style={{ marginTop: 16 }}>
            <Col xs={24}>
              <Card title={t("dashboard.topItems", "Top items today")} style={{ borderRadius: 12 }} loading={dailyLoading}>
                {(daily?.topItems ?? []).length === 0 ? (
                  <span style={{ color: "#9CA3AF", fontSize: 13 }}>{t("dashboard.noTopItems", "No item sales yet today")}</span>
                ) : (
                  <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 8 }}>
                    {(daily?.topItems ?? []).slice(0, 8).map((it) => (
                      <div key={it.menuItemId} style={{ padding: "8px 12px", background: "#F9FAFB", borderRadius: 8, border: "1px solid #E5E7EB" }}>
                        <div style={{ fontWeight: 600, fontSize: 14, color: "#111827" }}>{it.name}</div>
                        <div style={{ fontSize: 12, color: "#6B7280" }}>{it.qty} sold · RM {it.revenue}</div>
                      </div>
                    ))}
                  </div>
                )}
              </Card>
            </Col>
          </Row>
        </>
      )}
    </AdminShell>
  );
}
