import { useState } from "react";
import {
  Select, Button, Modal, Form, Input, InputNumber, Switch,
  Typography, Space, Popconfirm, message, Tag, Drawer, Collapse,
  Divider, Tooltip,
} from "antd";
import {
  PlusOutlined, EditOutlined, DeleteOutlined, UnorderedListOutlined,
} from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { MenuItem, MenuOptionGroup, MenuOptionChoice } from "@kawkaw/shared";
import { DataTable } from "../components/DataTable";
import { AdminShell } from "../layouts/AdminShell";
import { ImageUpload } from "../components/ImageUpload";
import {
  useAdminStalls, useAdminMenuItems,
  useCreateMenuItem, useUpdateMenuItem, useDeleteMenuItem,
  useCreateOptionGroup, useUpdateOptionGroup, useDeleteOptionGroup,
  useCreateOptionChoice, useUpdateOptionChoice, useDeleteOptionChoice,
  useAdminMenuCategories, useCreateMenuCategory, useUpdateMenuCategory, useDeleteMenuCategory,
  type MenuCategoryRow,
} from "../api/hooks";

const { Title, Text } = Typography;

/* ─────────────────────────────────────────────────────────
   Option Groups Drawer
   ───────────────────────────────────────────────────────── */
function OptionGroupsDrawer({
  open, item, onClose,
}: {
  open: boolean;
  item: MenuItem | null;
  onClose: () => void;
}) {
  const { t } = useTranslation();
  const [groupForm] = Form.useForm();
  const [choiceForm] = Form.useForm();
  const [editingGroup, setEditingGroup] = useState<MenuOptionGroup | null>(null);
  const [editingChoice, setEditingChoice] = useState<MenuOptionChoice | null>(null);
  const [addingGroupOpen, setAddingGroupOpen] = useState(false);
  const [addingChoiceForGroup, setAddingChoiceForGroup] = useState<string | null>(null);

  const createGroup = useCreateOptionGroup();
  const updateGroup = useUpdateOptionGroup();
  const deleteGroup = useDeleteOptionGroup();
  const createChoice = useCreateOptionChoice();
  const updateChoice = useUpdateOptionChoice();
  const deleteChoice = useDeleteOptionChoice();

  const groups: MenuOptionGroup[] = (item as (MenuItem & { option_groups?: MenuOptionGroup[] }))?.option_groups ?? [];

  // ── Group handlers ──
  const openAddGroup = () => { setEditingGroup(null); groupForm.resetFields(); setAddingGroupOpen(true); };
  const openEditGroup = (g: MenuOptionGroup) => {
    setEditingGroup(g);
    groupForm.setFieldsValue({ name: g.name, type: g.type, min_select: g.min_select, max_select: g.max_select, sort_order: g.sort_order });
    setAddingGroupOpen(true);
  };
  const saveGroup = async () => {
    try {
      const vals = await groupForm.validateFields();
      if (editingGroup) {
        await updateGroup.mutateAsync({ id: editingGroup.id, ...vals });
      } else {
        await createGroup.mutateAsync({ itemId: item!.id, ...vals });
      }
      void message.success(t("menu.groupSaved"));
      setAddingGroupOpen(false);
    } catch { void message.error(t("menu.saveFailed")); }
  };
  const removeGroup = async (id: string) => {
    try {
      await deleteGroup.mutateAsync(id);
      void message.success(t("menu.groupDeleted"));
    } catch { void message.error(t("menu.deleteFailed")); }
  };

  // ── Choice handlers ──
  const openAddChoice = (groupId: string) => {
    setEditingChoice(null); choiceForm.resetFields(); setAddingChoiceForGroup(groupId);
  };
  const openEditChoice = (c: MenuOptionChoice) => {
    setEditingChoice(c);
    choiceForm.setFieldsValue({ label: c.label, extra_charge: parseFloat(c.extra_charge ?? "0"), sort_order: c.sort_order });
    setAddingChoiceForGroup(c.group_id);
  };
  const saveChoice = async () => {
    try {
      const vals = await choiceForm.validateFields();
      if (editingChoice) {
        await updateChoice.mutateAsync({ id: editingChoice.id, ...vals });
      } else {
        await createChoice.mutateAsync({ groupId: addingChoiceForGroup!, ...vals });
      }
      void message.success(t("menu.choiceSaved"));
      setAddingChoiceForGroup(null);
    } catch { void message.error(t("menu.saveFailed")); }
  };
  const removeChoice = async (id: string) => {
    try {
      await deleteChoice.mutateAsync(id);
      void message.success(t("menu.choiceDeleted"));
    } catch { void message.error(t("menu.deleteFailed")); }
  };

  return (
    <Drawer
      open={open}
      title={t("menu.optionsDrawerTitle", { name: item?.name ?? "" })}
      onClose={onClose}
      width={520}
      extra={
        <Button type="primary" icon={<PlusOutlined />} onClick={openAddGroup}
          style={{ background: "#D97706", borderColor: "#D97706" }}>
          {t("menu.addGroup")}
        </Button>
      }
    >
      {groups.length === 0 && (
        <div style={{ textAlign: "center", color: "#9CA3AF", padding: "40px 0" }}>
          {t("common.noData")}
        </div>
      )}

      <Collapse accordion>
        {groups.map((g) => (
          <Collapse.Panel
            key={g.id}
            header={
              <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                <Text strong>{g.name}</Text>
                <Tag color={g.type === "required" ? "red" : "blue"}>
                  {g.type === "required" ? t("menu.groupTypeRequired") : t("menu.groupTypeOptional")}
                </Tag>
                <Text type="secondary" style={{ fontSize: 12 }}>
                  {g.min_select}–{g.max_select} {t("menu.groupMinSelect").toLowerCase()}
                </Text>
              </div>
            }
            extra={
              <Space onClick={(e) => e.stopPropagation()}>
                <Tooltip title={t("common.edit")}>
                  <Button size="small" icon={<EditOutlined />} onClick={() => openEditGroup(g)} />
                </Tooltip>
                <Popconfirm title={t("menu.confirmDeleteGroup")} onConfirm={() => void removeGroup(g.id)} okType="danger">
                  <Button size="small" danger icon={<DeleteOutlined />} />
                </Popconfirm>
              </Space>
            }
          >
            {/* Choices list */}
            {(g.choices ?? []).map((c) => (
              <div key={c.id} style={{
                display: "flex", alignItems: "center", justifyContent: "space-between",
                padding: "6px 8px", background: "#F9FAFB", borderRadius: 6, marginBottom: 4,
              }}>
                <div>
                  <Text>{c.label}</Text>
                  {parseFloat(c.extra_charge ?? "0") > 0 && (
                    <Tag color="orange" style={{ marginLeft: 8 }}>+RM {parseFloat(c.extra_charge).toFixed(2)}</Tag>
                  )}
                </div>
                <Space>
                  <Button size="small" icon={<EditOutlined />} onClick={() => openEditChoice(c)} />
                  <Popconfirm title={t("menu.confirmDeleteChoice")} onConfirm={() => void removeChoice(c.id)} okType="danger">
                    <Button size="small" danger icon={<DeleteOutlined />} />
                  </Popconfirm>
                </Space>
              </div>
            ))}

            <Button size="small" icon={<PlusOutlined />} onClick={() => openAddChoice(g.id)}
              style={{ marginTop: 6, borderStyle: "dashed" }}>
              {t("menu.addChoice")}
            </Button>
          </Collapse.Panel>
        ))}
      </Collapse>

      {/* Add/Edit Group Modal */}
      <Modal
        open={addingGroupOpen}
        title={editingGroup ? t("menu.editGroup") : t("menu.addGroup")}
        onCancel={() => setAddingGroupOpen(false)}
        onOk={() => void saveGroup()}
        okText={t("common.save")}
        okButtonProps={{ loading: createGroup.isPending || updateGroup.isPending, style: { background: "#D97706", borderColor: "#D97706" } }}
        destroyOnHidden
      >
        <Form form={groupForm} layout="vertical">
          <Form.Item name="name" label={t("menu.groupName")} rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="type" label={t("menu.groupType")} rules={[{ required: true }]} initialValue="optional">
            <Select options={[
              { value: "required", label: t("menu.groupTypeRequired") },
              { value: "optional", label: t("menu.groupTypeOptional") },
            ]} />
          </Form.Item>
          <Form.Item name="min_select" label={t("menu.groupMinSelect")} initialValue={0}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="max_select" label={t("menu.groupMaxSelect")} initialValue={1}>
            <InputNumber min={1} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="sort_order" label={t("menu.formSortOrder")} initialValue={0}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
        </Form>
      </Modal>

      {/* Add/Edit Choice Modal */}
      <Modal
        open={addingChoiceForGroup !== null}
        title={editingChoice ? t("menu.editChoice") : t("menu.addChoice")}
        onCancel={() => setAddingChoiceForGroup(null)}
        onOk={() => void saveChoice()}
        okText={t("common.save")}
        okButtonProps={{ loading: createChoice.isPending || updateChoice.isPending, style: { background: "#D97706", borderColor: "#D97706" } }}
        destroyOnHidden
      >
        <Form form={choiceForm} layout="vertical">
          <Form.Item name="label" label={t("menu.choiceLabel")} rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="extra_charge" label={t("menu.choiceExtraCharge")} initialValue={0}>
            <InputNumber prefix="RM" min={0} precision={2} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="sort_order" label={t("menu.formSortOrder")} initialValue={0}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
        </Form>
      </Modal>
    </Drawer>
  );
}

/* ─────────────────────────────────────────────────────────
   Main MenuScreen
   ───────────────────────────────────────────────────────── */
export function MenuScreen() {
  const { t } = useTranslation();
  const [stallId, setStallId] = useState<string | undefined>();
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<MenuItem | null>(null);
  const [optionsItemId, setOptionsItemId] = useState<string | null>(null);
  const [catDrawerOpen, setCatDrawerOpen] = useState(false);
  const [form] = Form.useForm();

  // Declare data hooks first so derived values below can reference them
  const { data: stallsData } = useAdminStalls();
  const { data: menuData, isLoading } = useAdminMenuItems(stallId);
  const { data: catData } = useAdminMenuCategories(stallId);
  const { data: allCatData } = useAdminMenuCategories(); // all categories (no stall filter) for item form

  // Derived from live data
  const categories: MenuCategoryRow[] = catData?.data ?? [];
  const allCategories: MenuCategoryRow[] = allCatData?.data ?? [];
  const selectedStallName = (stallsData?.data ?? []).find((s) => s.id === stallId)?.name ?? "";
  // Always derive from live data so drawer updates after mutations
  const optionsItem = optionsItemId
    ? (menuData?.data ?? []).find((it) => it.id === optionsItemId) ?? null
    : null;
  const createItem = useCreateMenuItem();
  const updateItem = useUpdateMenuItem();
  const deleteItem = useDeleteMenuItem();

  const openCreate = () => { setEditing(null); form.resetFields(); setModalOpen(true); };
  const openEdit = (item: MenuItem) => {
    setEditing(item);
    const row = item as MenuItem & { categories?: Array<{ id: string }>; category_ids?: string[] };
    const categoryIds = row.categories?.map((c) => c.id) ?? row.category_ids ?? [];
    form.setFieldsValue({
      ...item,
      stall_id: stallId,
      category_ids: categoryIds,
      offer_price: item.offer_price ? parseFloat(item.offer_price as unknown as string) : undefined,
    });
    setModalOpen(true);
  };

  const onSave = async (values: Partial<MenuItem>) => {
    try {
      if (editing) {
        await updateItem.mutateAsync({ id: editing.id, ...values });
        void message.success(t("menu.updateSuccess"));
      } else {
        await createItem.mutateAsync({ ...values, stall_id: stallId });
        void message.success(t("menu.createSuccess"));
      }
      setModalOpen(false);
    } catch {
      void message.error(t("menu.saveFailed"));
    }
  };

  const onDelete = async (id: string) => {
    try {
      await deleteItem.mutateAsync(id);
      void message.success(t("menu.deleteSuccess"));
    } catch {
      void message.error(t("menu.deleteFailed"));
    }
  };

  const columns: ColumnsType<MenuItem> = [
    {
      title: t("menu.colImage"), dataIndex: "image_url", key: "img", width: 60,
      render: (url: string | null) => url
        ? <img src={url} alt="" style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 6 }} />
        : <div style={{ width: 40, height: 40, background: "#F3F4F6", borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center" }}>—</div>,
    },
    { title: t("menu.colName"), dataIndex: "name", key: "name" },
    {
      title: t("menu.colCategory"), key: "category", width: 160,
      render: (_: unknown, row: MenuItem) => {
        const r = row as MenuItem & { categories?: Array<{ id: string }>; category_ids?: string[] };
        const catIds = r.categories?.map((c) => c.id) ?? r.category_ids ?? [];
        if (!catIds.length) return <Text type="secondary">—</Text>;
        return <>{catIds.map((id) => {
          const cat = allCategories.find((c) => c.id === id);
          return cat ? <Tag key={id}>{cat.emoji ? `${cat.emoji} ` : ""}{cat.name}</Tag> : null;
        })}</>;
      },
    },
    {
      title: t("menu.colPrice"), key: "price", width: 140,
      render: (_, row) => {
        const offerPrice = (row as MenuItem & { offer_price?: string }).offer_price;
        return (
          <div>
            <b>RM {row.price}</b>
            {offerPrice && (
              <Tag color="orange" style={{ marginLeft: 6, fontSize: 11 }}>🏷 RM {parseFloat(offerPrice).toFixed(2)}</Tag>
            )}
          </div>
        );
      },
    },
    {
      title: t("menu.colAvailable"), dataIndex: "is_available", key: "available", width: 100,
      render: (v: boolean) => <Tag color={v ? "success" : "error"}>{v ? t("common.yes") : t("common.no")}</Tag>,
    },
    {
      title: t("menu.colStock"), dataIndex: "daily_stock", key: "stock", width: 80,
      render: (v: number | null, row) => v != null ? `${row.sold_today_count ?? 0}/${v}` : "∞",
    },
    {
      title: "", key: "actions", width: 120, fixed: "right",
      render: (_, row) => (
        <Space>
          <Tooltip title={t("menu.manageOptions")}>
            <Button size="small" icon={<UnorderedListOutlined />} onClick={() => setOptionsItemId(row.id)} />
          </Tooltip>
          <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(row)} />
          <Popconfirm title={t("common.confirmDelete")} onConfirm={() => void onDelete(row.id)} okType="danger">
            <Button size="small" danger icon={<DeleteOutlined />} />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <AdminShell>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <Title level={4} style={{ margin: 0 }}>{t("menu.title")}</Title>
        <Space>
          <Select
            placeholder={t("common.selectStall")}
            value={stallId}
            onChange={setStallId}
            style={{ width: 200 }}
            options={(stallsData?.data ?? []).map((s) => ({ value: s.id, label: s.name }))}
          />
          <Button icon={<UnorderedListOutlined />} onClick={() => setCatDrawerOpen(true)} disabled={!stallId}>
            {t("menu.manageCategories")}
          </Button>
          <Button type="primary" icon={<PlusOutlined />} onClick={openCreate} disabled={!stallId}
            style={{ background: "#D97706", borderColor: "#D97706" }}>
            {t("menu.addItem")}
          </Button>
        </Space>
      </div>

      {!stallId ? (
        <div style={{ padding: 40, textAlign: "center", color: "#9CA3AF" }}>{t("menu.selectStallPrompt")}</div>
      ) : (
        <DataTable<MenuItem>
          columns={columns}
          dataSource={menuData?.data ?? []}
          loading={isLoading}
        />
      )}

      {/* Add/Edit Item Modal */}
      <Modal
        open={modalOpen}
        title={editing ? t("menu.editTitle") : t("menu.addTitle")}
        onCancel={() => setModalOpen(false)}
        onOk={() => void form.submit()}
        okText={t("common.save")}
        okButtonProps={{ style: { background: "#D97706", borderColor: "#D97706" }, loading: createItem.isPending || updateItem.isPending }}
        width={640}
      >
        <Form form={form} layout="vertical" onFinish={onSave}>
          <Form.Item name="image_url" label={t("menu.formImage")}>
            <ImageUpload folder="menu" />
          </Form.Item>
          <Form.Item name="name" label={t("menu.formName")} rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="description" label={t("menu.formDescription")}>
            <Input.TextArea rows={2} />
          </Form.Item>
          <Form.Item name="category_ids" label={t("menu.formCategoryId")}>
            <Select
              mode="multiple"
              allowClear
              placeholder={t("menu.formCategoryPlaceholder")}
              options={allCategories.map((c) => ({ value: c.id, label: `${c.emoji ? c.emoji + " " : ""}${c.name}` }))}
              notFoundContent={
                <div style={{ textAlign: "center", padding: "8px 0", fontSize: 12, color: "#9CA3AF" }}>
                  {t("menu.addCategory")}
                </div>
              }
            />
          </Form.Item>
          <Form.Item name="price" label={t("menu.formPrice")} rules={[{ required: true }]}>
            <InputNumber prefix="RM" min={0} precision={2} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="daily_stock" label={t("menu.formDailyStock")}>
            <InputNumber min={1} style={{ width: "100%" }} placeholder="e.g. 50" />
          </Form.Item>
          <Form.Item name="available_from" label={t("menu.formAvailableFrom")}>
            <Input placeholder="07:00" maxLength={5} />
          </Form.Item>
          <Form.Item name="available_to" label={t("menu.formAvailableTo")}>
            <Input placeholder="22:00" maxLength={5} />
          </Form.Item>

          <Divider orientation="left" style={{ fontSize: 13, color: "#D97706" }}>🏷 {t("menu.formOfferPrice")}</Divider>
          <Form.Item name="offer_price" label={t("menu.formOfferPrice")}>
            <InputNumber prefix="RM" min={0} precision={2} style={{ width: "100%" }} placeholder="e.g. 4.50" />
          </Form.Item>
          <Form.Item name="offer_from" label={t("menu.formOfferFrom")}>
            <Input placeholder="10:00" maxLength={5} />
          </Form.Item>
          <Form.Item name="offer_to" label={t("menu.formOfferTo")}>
            <Input placeholder="14:00" maxLength={5} />
          </Form.Item>

          <Divider />
          <Form.Item name="is_available" label={t("menu.formIsAvailable")} valuePropName="checked" initialValue={true}>
            <Switch checkedChildren={t("common.yes")} unCheckedChildren={t("common.no")} />
          </Form.Item>
          <Form.Item name="sort_order" label={t("menu.formSortOrder")} initialValue={0}>
            <InputNumber min={0} style={{ width: "100%" }} />
          </Form.Item>
        </Form>
      </Modal>

      {/* Option Groups Drawer */}
      <OptionGroupsDrawer
        open={!!optionsItemId}
        item={optionsItem}
        onClose={() => setOptionsItemId(null)}
      />
    </AdminShell>
  );
}
