import { useState } from "react";
import {
  Button, Modal, Form, Input, Select, Space, Typography,
  message, Tag, Tooltip, Popconfirm, Switch,
} from "antd";
import { PlusOutlined, EditOutlined, KeyOutlined, DeleteOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { Staff } from "@kawkaw/shared";
import dayjs from "dayjs";
import { DataTable } from "../components/DataTable";
import { StatusTag } from "../components/StatusTag";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminStaff, useAdminStalls, useCreateStaff, useUpdateStaff, useResetStaffPin, useDeleteStaff } from "../api/hooks";
import { useAuthStore } from "../store/auth";

const { Title } = Typography;

export function StaffScreen() {
  const { t } = useTranslation();
  const [modalOpen, setModalOpen] = useState(false);
  const [pinModalOpen, setPinModalOpen] = useState(false);
  const [editing, setEditing] = useState<Staff | null>(null);
  const [pinTarget, setPinTarget] = useState<Staff | null>(null);
  const [form] = Form.useForm();
  const [pinForm] = Form.useForm<{ newPin: string; confirm: string }>();

  const { data, isLoading } = useAdminStaff();
  const { data: stallsData } = useAdminStalls();
  const createStaff = useCreateStaff();
  const updateStaff = useUpdateStaff();
  const resetPin = useResetStaffPin();
  const deleteStaff = useDeleteStaff();
  const meId = useAuthStore((s) => s.staff?.id);

  const ROLES = [
    { value: "admin", label: "Admin" },
    { value: "pos_operator", label: "POS Operator" },
    { value: "stall_staff", label: "Stall Staff" },
  ];

  const openCreate = () => { setEditing(null); form.resetFields(); setModalOpen(true); };
  const openEdit = (s: Staff) => { setEditing(s); form.setFieldsValue(s); setModalOpen(true); };
  const openPin = (s: Staff) => { setPinTarget(s); pinForm.resetFields(); setPinModalOpen(true); };

  const onSave = async (values: Partial<Staff> & { pin?: string }) => {
    try {
      if (editing) {
        await updateStaff.mutateAsync({ id: editing.id, ...values });
        void message.success(t("staff.updateSuccess"));
      } else {
        await createStaff.mutateAsync(values as Parameters<typeof createStaff.mutateAsync>[0]);
        void message.success(t("staff.createSuccess"));
      }
      setModalOpen(false);
    } catch {
      void message.error(t("staff.saveFailed"));
    }
  };

  const onResetPin = async (values: { newPin: string }) => {
    if (!pinTarget) return;
    try {
      const result = await resetPin.mutateAsync({ id: pinTarget.id, newPin: values.newPin }) as { data?: { tempPin?: string } };
      const tempPin = result?.data?.tempPin;
      if (tempPin) {
        void message.success(t("staff.pinResetSuccess", { pin: tempPin }), 8);
      } else {
        void message.success(t("staff.pinResetSuccessSimple"));
      }
      setPinModalOpen(false);
      pinForm.resetFields();
    } catch {
      void message.error(t("staff.pinResetFailed"));
    }
  };

  const columns: ColumnsType<Staff> = [
    { title: t("staff.colName"), dataIndex: "name", key: "name" },
    {
      title: t("staff.colPhone"), dataIndex: "phone", key: "phone", width: 140,
      render: (v) => <span style={{ fontFamily: "monospace" }}>{v}</span>,
    },
    {
      title: t("staff.colRole"), dataIndex: "role", key: "role", width: 120,
      render: (v) => <Tag color={v === "superadmin" ? "red" : v === "admin" ? "orange" : "blue"}>{v}</Tag>,
    },
    {
      title: t("staff.colStall"), dataIndex: ["stall", "name"], key: "stall", width: 160,
      render: (v) => v ?? <span style={{ color: "#9CA3AF" }}>—</span>,
    },
    {
      title: t("staff.colStatus"), dataIndex: "is_active", key: "status", width: 110,
      render: (v, row) => (
        <Space size={6}>
          <StatusTag status={v ? "active" : "inactive"} />
          <Switch
            size="small"
            checked={!!v}
            disabled={row.id === meId}
            onChange={async (checked) => {
              try {
                await updateStaff.mutateAsync({ id: row.id, is_active: checked });
                void message.success(checked ? t("staff.activated", "Staff activated") : t("staff.deactivated", "Staff deactivated"));
              } catch {
                void message.error(t("staff.saveFailed"));
              }
            }}
          />
        </Space>
      ),
    },
    {
      title: t("staff.colCreated"), dataIndex: "created_at", key: "created", width: 130,
      render: (v) => v ? dayjs(v).format("DD MMM YYYY") : "—",
    },
    {
      title: "", key: "actions", width: 140, fixed: "right",
      render: (_, row) => (
        <Space>
          <Tooltip title={t("staff.tooltipEdit")}><Button size="small" icon={<EditOutlined />} onClick={() => openEdit(row)} /></Tooltip>
          <Tooltip title={t("staff.tooltipResetPin")}><Button size="small" icon={<KeyOutlined />} onClick={() => openPin(row)} /></Tooltip>
          <Popconfirm
            title={t("staff.deleteConfirm", "Remove this staff member?")}
            description={t("staff.deleteConfirmDesc", "Their account will be deactivated and they won't be able to log in.")}
            okText={t("common.yes", "Yes")}
            cancelText={t("common.no", "No")}
            onConfirm={async () => {
              try {
                await deleteStaff.mutateAsync(row.id);
                void message.success(t("staff.deleteSuccess", "Staff removed"));
              } catch {
                void message.error(t("staff.deleteFailed", "Failed to remove staff"));
              }
            }}
          >
            <Tooltip title={t("staff.tooltipDelete", "Remove staff")}>
              <Button size="small" danger icon={<DeleteOutlined />} disabled={row.id === meId} />
            </Tooltip>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <AdminShell>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <Title level={4} style={{ margin: 0 }}>{t("staff.title")}</Title>
        <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}
          style={{ background: "#D97706", borderColor: "#D97706" }}>
          {t("staff.addStaff")}
        </Button>
      </div>

      <DataTable<Staff> columns={columns} dataSource={data?.data ?? []} loading={isLoading} />

      {/* Create / Edit Modal */}
      <Modal
        open={modalOpen}
        title={editing ? t("staff.editTitle") : t("staff.addTitle")}
        onCancel={() => setModalOpen(false)}
        onOk={() => void form.submit()}
        okButtonProps={{ style: { background: "#D97706", borderColor: "#D97706" }, loading: createStaff.isPending || updateStaff.isPending }}
      >
        <Form form={form} layout="vertical" onFinish={onSave}>
          <Form.Item name="name" label={t("staff.formFullName")} rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="phone" label={t("staff.formPhone")} rules={[{ required: true }]}>
            <Input disabled={!!editing} />
          </Form.Item>
          {!editing && (
            <Form.Item name="pin" label={t("staff.formInitialPin")} rules={[{ required: true, len: 4, message: t("staff.formPinLengthMsg") }]}>
              <Input.Password maxLength={4} placeholder="4-digit PIN" />
            </Form.Item>
          )}
          <Form.Item name="role" label={t("staff.formRole")} rules={[{ required: true }]}>
            <Select options={ROLES} />
          </Form.Item>
          <Form.Item name="stall_id" label={t("staff.formAssignedStall")}>
            <Select
              allowClear
              options={(stallsData?.data ?? []).map((s) => ({ value: s.id, label: s.name }))}
            />
          </Form.Item>
        </Form>
      </Modal>

      {/* Reset PIN Modal */}
      <Modal
        open={pinModalOpen}
        title={`${t("staff.resetPinTitle")} — ${pinTarget?.name ?? ""}`}
        onCancel={() => setPinModalOpen(false)}
        onOk={() => void pinForm.submit()}
        okText={t("staff.resetPinBtn")}
        okButtonProps={{ loading: resetPin.isPending }}
      >
        <Form form={pinForm} layout="vertical" onFinish={onResetPin}>
          <Form.Item name="newPin" label={t("staff.formNewPin")} rules={[{ required: true }, { min: 4, max: 6, message: t("staff.pinDigitsMsg") }]}>
            <Input.Password maxLength={6} placeholder="4–6 digit PIN" />
          </Form.Item>
          <Form.Item
            name="confirm"
            label={t("staff.formConfirmPin")}
            dependencies={["newPin"]}
            rules={[
              { required: true },
              ({ getFieldValue }) => ({
                validator: (_, value) =>
                  !value || getFieldValue("newPin") === value
                    ? Promise.resolve()
                    : Promise.reject(new Error(t("staff.pinMismatch"))),
              }),
            ]}
          >
            <Input.Password maxLength={6} placeholder="Re-enter PIN" />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
