import { useState } from "react";
import { Card, Row, Col, Typography, Select, DatePicker, Space, Table } from "antd";
import {
  LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid,
  Tooltip, Legend, ResponsiveContainer,
} from "recharts";
import { useTranslation } from "react-i18next";
import dayjs from "dayjs";
import type { Dayjs } from "dayjs";
import { AdminShell } from "../layouts/AdminShell";
import { useRevenueReport, useStallBreakdown } from "../api/hooks";

const { Title, Text } = Typography;
const { RangePicker } = DatePicker;

type Granularity = "hourly" | "daily" | "weekly" | "monthly";

export function ReportsScreen() {
  const { t } = useTranslation();
  const [granularity, setGranularity] = useState<Granularity>("daily");
  const [range, setRange] = useState<[Dayjs, Dayjs]>([dayjs().subtract(6, "day"), dayjs()]);

  const params = {
    from: range[0].format("YYYY-MM-DD"),
    to: range[1].format("YYYY-MM-DD"),
    granularity,
  };

  const { data: revenueData, isLoading: revLoading } = useRevenueReport(params);
  const { data: stallData, isLoading: stallLoading } = useStallBreakdown(params);

  const chartData = (revenueData?.data ?? []).map((d) => ({
    ...d,
    revenue: parseFloat(d.revenue),
  }));

  const stallColumns = [
    { title: t("reports.colStall"), dataIndex: "stallName", key: "stall" },
    { title: t("reports.colRevenue"), dataIndex: "revenue", key: "revenue", render: (v: string) => `RM ${v}` },
    { title: t("reports.colOrders"), dataIndex: "orders", key: "orders" },
    { title: t("reports.colAvgOrder"), dataIndex: "avgOrderValue", key: "avg", render: (v: string) => `RM ${v}` },
  ];

  return (
    <AdminShell>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
        <Title level={4} style={{ margin: 0 }}>{t("reports.title")}</Title>
        <Space>
          <Select
            value={granularity}
            onChange={setGranularity}
            style={{ width: 120 }}
            options={[
              { value: "hourly", label: t("reports.granularityHourly") },
              { value: "daily", label: t("reports.granularityDaily") },
              { value: "weekly", label: t("reports.granularityWeekly") },
              { value: "monthly", label: t("reports.granularityMonthly") },
            ]}
          />
          <RangePicker
            value={range}
            onChange={(dates) => { if (dates?.[0] && dates[1]) setRange([dates[0], dates[1]]); }}
            allowClear={false}
            presets={[
              { label: t("reports.presetToday"), value: [dayjs(), dayjs()] },
              { label: t("reports.presetLast7"), value: [dayjs().subtract(6, "day"), dayjs()] },
              { label: t("reports.presetLast30"), value: [dayjs().subtract(29, "day"), dayjs()] },
              { label: t("reports.presetThisMonth"), value: [dayjs().startOf("month"), dayjs().endOf("month")] },
            ]}
          />
        </Space>
      </div>

      <Row gutter={[16, 16]}>
        {/* Revenue Line Chart */}
        <Col span={24}>
          <Card title={t("reports.chartRevenueOrders")} loading={revLoading} style={{ borderRadius: 12 }}>
            {chartData.length === 0 ? (
              <div style={{ height: 280, display: "flex", alignItems: "center", justifyContent: "center", color: "#9CA3AF" }}>
                {t("reports.chartNoData")}
              </div>
            ) : (
              <ResponsiveContainer width="100%" height={280}>
                <LineChart data={chartData} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#F3F4F6" />
                  <XAxis dataKey="label" tick={{ fontSize: 12, fill: "#6B7280" }} />
                  <YAxis yAxisId="rev" orientation="left" tick={{ fontSize: 12, fill: "#6B7280" }}
                    tickFormatter={(v) => `RM${v}`} />
                  <YAxis yAxisId="ord" orientation="right" tick={{ fontSize: 12, fill: "#6B7280" }} />
                  <Tooltip
                    formatter={(v, name) => name === "revenue" ? [`RM ${Number(v).toFixed(2)}`, t("reports.colRevenue")] : [v, t("reports.colOrders")]}
                  />
                  <Legend />
                  <Line yAxisId="rev" type="monotone" dataKey="revenue" stroke="#D97706" strokeWidth={2}
                    dot={{ r: 3 }} activeDot={{ r: 5 }} name={t("reports.colRevenue")} />
                  <Line yAxisId="ord" type="monotone" dataKey="orders" stroke="#3B82F6" strokeWidth={2}
                    dot={{ r: 3 }} activeDot={{ r: 5 }} name={t("reports.colOrders")} />
                </LineChart>
              </ResponsiveContainer>
            )}
          </Card>
        </Col>

        {/* Stall Revenue BarChart */}
        <Col xs={24} lg={12}>
          <Card title={t("reports.chartRevenueByStall")} loading={stallLoading} style={{ borderRadius: 12 }}>
            {(stallData?.data ?? []).length === 0 ? (
              <div style={{ height: 240, display: "flex", alignItems: "center", justifyContent: "center", color: "#9CA3AF" }}>
                {t("reports.chartNoDataShort")}
              </div>
            ) : (
              <ResponsiveContainer width="100%" height={240}>
                <BarChart data={stallData?.data ?? []} margin={{ top: 5, right: 10, bottom: 20, left: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#F3F4F6" />
                  <XAxis dataKey="stallName" tick={{ fontSize: 11, fill: "#6B7280" }} angle={-15} textAnchor="end" />
                  <YAxis tick={{ fontSize: 12, fill: "#6B7280" }} tickFormatter={(v) => `RM${v}`} />
                  <Tooltip formatter={(v) => [`RM ${Number(v).toFixed(2)}`, t("reports.colRevenue")]} />
                  <Bar dataKey="revenue" fill="#D97706" radius={[4, 4, 0, 0]}
                    label={{ position: "top", fontSize: 11, formatter: (v: unknown) => `RM${Number(v).toFixed(0)}` }} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </Card>
        </Col>

        {/* Stall Breakdown Table */}
        <Col xs={24} lg={12}>
          <Card title={t("reports.tableStallBreakdown")} loading={stallLoading} style={{ borderRadius: 12 }}>
            <Table
              size="small"
              columns={stallColumns}
              dataSource={stallData?.data ?? []}
              rowKey="stallName"
              pagination={false}
              summary={(rows) => {
                const totalRev = rows.reduce((s, r) => s + parseFloat(r.revenue), 0);
                const totalOrd = rows.reduce((s, r) => s + r.orders, 0);
                return (
                  <Table.Summary.Row style={{ fontWeight: 700, background: "#FEF3C7" }}>
                    <Table.Summary.Cell index={0}>{t("reports.tableTotal")}</Table.Summary.Cell>
                    <Table.Summary.Cell index={1}>RM {totalRev.toFixed(2)}</Table.Summary.Cell>
                    <Table.Summary.Cell index={2}>{totalOrd}</Table.Summary.Cell>
                    <Table.Summary.Cell index={3}>RM {totalOrd ? (totalRev / totalOrd).toFixed(2) : "0.00"}</Table.Summary.Cell>
                  </Table.Summary.Row>
                );
              }}
            />
          </Card>
        </Col>
      </Row>

      {/* Summary note */}
      <div style={{ marginTop: 12, color: "#9CA3AF", fontSize: 12 }}>
        <Text type="secondary">
          {t("reports.dataRange", { from: range[0].format("D MMM YYYY"), to: range[1].format("D MMM YYYY") })}
        </Text>
      </div>
    </AdminShell>
  );
}
