import { useState } from "react";
import { Card, Form, Input, InputNumber, Button, Typography, Divider, App, Row, Col } from "antd";
import { useTranslation } from "react-i18next";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminSettings, useUpdateSettings } from "../api/hooks";

const { Title, Text } = Typography;

export function SettingsScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const { data, isLoading } = useAdminSettings();
  const update = useUpdateSettings();
  const [form] = Form.useForm();
  const [saving, setSaving] = useState(false);

  const settings = data?.data as Record<string, unknown> | undefined;

  const onSave = async (values: Record<string, unknown>) => {
    setSaving(true);
    try {
      const payload: Record<string, unknown> = {
        name: values.name,
        address: values.address,
        phone: values.phone,
        sst_rate: values.sst_rate != null ? Number(values.sst_rate) / 100 : undefined,
        delivery_fee_default: values.delivery_fee_default != null ? Number(values.delivery_fee_default) : undefined,
      };
      await update.mutateAsync(payload);
      void message.success(t("settings.saveSuccess"));
    } catch {
      void message.error(t("settings.saveFailed"));
    } finally {
      setSaving(false);
    }
  };

  const initialValues = settings ? {
    ...settings,
    sst_rate: settings.sst_rate != null ? (parseFloat(String(settings.sst_rate)) * 100).toFixed(1) : 6,
    delivery_fee_default: settings.delivery_fee_default,
  } : undefined;

  return (
    <AdminShell>
      <Title level={4} style={{ marginBottom: 20 }}>{t("settings.title")}</Title>
      <Row>
        <Col xs={24} lg={16} xl={12}>
          <Card style={{ borderRadius: 12 }} loading={isLoading}>
            <Form
              form={form}
              layout="vertical"
              onFinish={onSave}
              initialValues={initialValues}
              key={JSON.stringify(initialValues)}
            >
              <Divider orientation="left" plain>
                <Text type="secondary" style={{ fontSize: 12 }}>{t("settings.sectionBusiness")}</Text>
              </Divider>

              <Form.Item name="name" label={t("settings.fieldKopitiamName")} rules={[{ required: true }]}>
                <Input />
              </Form.Item>
              <Form.Item name="address" label={t("settings.fieldAddress")} rules={[{ required: true }]}>
                <Input.TextArea rows={2} />
              </Form.Item>
              <Form.Item name="phone" label={t("settings.fieldPhone")}>
                <Input />
              </Form.Item>

              <Divider orientation="left" plain>
                <Text type="secondary" style={{ fontSize: 12 }}>{t("settings.sectionTax")}</Text>
              </Divider>

              <Row gutter={12}>
                <Col span={12}>
                  <Form.Item
                    name="sst_rate"
                    label={t("settings.fieldSstRate")}
                    tooltip={t("settings.fieldSstTooltip")}
                    rules={[{ required: true }]}
                  >
                    <InputNumber
                      min={0} max={100} precision={1} suffix="%"
                      style={{ width: "100%" }}
                    />
                  </Form.Item>
                </Col>
                <Col span={12}>
                  <Form.Item
                    name="delivery_fee_default"
                    label={t("settings.fieldDeliveryFee")}
                    tooltip={t("settings.fieldDeliveryFeeTooltip")}
                  >
                    <InputNumber
                      min={0} precision={2} prefix="RM"
                      style={{ width: "100%" }}
                    />
                  </Form.Item>
                </Col>
              </Row>

              <Form.Item style={{ marginTop: 8 }}>
                <Button type="primary" htmlType="submit" loading={saving}
                  style={{ background: "#D97706", borderColor: "#D97706" }}>
                  {t("settings.saveBtn")}
                </Button>
              </Form.Item>
            </Form>
          </Card>
        </Col>
      </Row>
    </AdminShell>
  );
}
