import { useState } from "react";
import { Select, Space, Typography, Button, Modal, Input, Form, App } from "antd";
import { CheckOutlined, CloseOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import dayjs from "dayjs";
import { DataTable } from "../components/DataTable";
import { StatusTag } from "../components/StatusTag";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminRefunds, useReviewRefund } from "../api/hooks";

const { Title, Text } = Typography;

interface Refund {
  id: string;
  amount: string;
  status: string;
  reason: string;
  created_at: string;
  transaction: { amount: string; method: string; reference: string | null };
}

export function RefundsScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const [page, setPage] = useState(1);
  const [status, setStatus] = useState<string | undefined>();
  const [reviewTarget, setReviewTarget] = useState<{ id: string; action: "approve" | "reject" } | null>(null);
  const [noteForm] = Form.useForm<{ note: string }>();
  const reviewRefund = useReviewRefund();

  const { data, isLoading } = useAdminRefunds({ page, limit: 20, status });

  const onReview = async (values: { note?: string }) => {
    if (!reviewTarget) return;
    try {
      await reviewRefund.mutateAsync({ ...reviewTarget, note: values.note });
      void message.success(reviewTarget.action === "approve" ? t("refunds.approvedMsg") : t("refunds.rejectedMsg"));
      setReviewTarget(null);
      noteForm.resetFields();
    } catch {
      void message.error(t("refunds.reviewFailed"));
    }
  };

  const columns: ColumnsType<Refund> = [
    {
      title: t("refunds.colId"), dataIndex: "id", key: "id", width: 120,
      render: (v: string) => <Text code style={{ fontSize: 11 }}>{v.slice(-8)}</Text>,
    },
    {
      title: t("refunds.colAmount"), dataIndex: "amount", key: "amount", width: 110,
      render: (v: string) => <Text strong>RM {v}</Text>,
    },
    {
      title: t("refunds.colReason"), dataIndex: "reason", key: "reason",
      render: (v: string) => <Text style={{ fontSize: 13 }}>{v}</Text>,
    },
    {
      title: t("refunds.colPaymentRef"), dataIndex: ["transaction", "reference"], key: "ref", width: 160,
      render: (v: string | null) => v ? <Text code style={{ fontSize: 11 }}>{v}</Text> : "—",
    },
    {
      title: t("refunds.colStatus"), dataIndex: "status", key: "status", width: 130,
      render: (v: string) => <StatusTag status={v} />,
    },
    {
      title: t("refunds.colRequested"), dataIndex: "created_at", key: "created_at", width: 150,
      render: (v: string) => dayjs(v).format("DD MMM YYYY HH:mm"),
    },
    {
      title: t("refunds.colActions"), key: "actions", width: 160, fixed: "right",
      render: (_, row: Refund) => row.status === "pending" ? (
        <Space>
          <Button size="small" type="primary" icon={<CheckOutlined />}
            style={{ background: "#10B981", borderColor: "#10B981" }}
            onClick={() => setReviewTarget({ id: row.id, action: "approve" })}>
            {t("refunds.approve")}
          </Button>
          <Button size="small" danger icon={<CloseOutlined />}
            onClick={() => setReviewTarget({ id: row.id, action: "reject" })}>
            {t("refunds.reject")}
          </Button>
        </Space>
      ) : null,
    },
  ];

  return (
    <AdminShell>
      <Title level={4} style={{ marginBottom: 16 }}>{t("refunds.title")}</Title>

      <Space style={{ marginBottom: 16 }}>
        <Select placeholder={t("refunds.filterStatus")} allowClear value={status} onChange={setStatus} style={{ width: 180 }}
          options={[
            { value: "pending_review", label: t("refunds.statusPendingReview") },
            { value: "approved", label: t("refunds.statusApproved") },
            { value: "rejected", label: t("refunds.statusRejected") },
          ]}
        />
      </Space>

      <DataTable<Refund>
        columns={columns}
        dataSource={(data?.data ?? []) as unknown as Refund[]}
        loading={isLoading}
        pagination={{ current: page, total: data?.meta.total ?? 0, pageSize: 20, onChange: (p) => setPage(p) }}
      />

      <Modal
        open={!!reviewTarget}
        title={reviewTarget?.action === "approve" ? t("refunds.approveTitle") : t("refunds.rejectTitle")}
        onCancel={() => { setReviewTarget(null); noteForm.resetFields(); }}
        onOk={() => void noteForm.submit()}
        okText={reviewTarget?.action === "approve" ? t("refunds.approve") : t("refunds.reject")}
        okButtonProps={{
          loading: reviewRefund.isPending,
          style: reviewTarget?.action === "approve" ? { background: "#10B981", borderColor: "#10B981" } : {},
          danger: reviewTarget?.action === "reject",
        }}
      >
        <Form form={noteForm} layout="vertical" onFinish={onReview}>
          <Form.Item name="note" label={t("refunds.noteLabel")}>
            <Input.TextArea rows={3} placeholder={t("refunds.notePlaceholder")} />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
