import { useState } from "react";
import { Input, Select, DatePicker, Space, Typography, Button, Tag, Modal, Form, InputNumber, App } from "antd";
import { SearchOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { Transaction } from "@kawkaw/shared";
import dayjs from "dayjs";
import { DataTable } from "../components/DataTable";
import { StatusTag } from "../components/StatusTag";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminTransactions, useInitiateRefund } from "../api/hooks";

const { Title, Text } = Typography;
const { RangePicker } = DatePicker;

// Backend transaction includes order join: { id, order_code, type, total }
type TxnWithOrder = Transaction & {
  reference: string | null;
  method: string;
  order?: { id: string; order_code: string; type: string; total: string };
};

const REFUND_METHODS = [
  { value: "cash", label: "Cash" }, { value: "fpx", label: "FPX" },
  { value: "visa", label: "Visa/Card" }, { value: "grabpay", label: "GrabPay" },
  { value: "tng", label: "Touch 'n Go" }, { value: "boost", label: "Boost" },
  { value: "ewallet", label: "eWallet" },
];

export function TransactionsScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState<string | undefined>();
  const [dateRange, setDateRange] = useState<[string, string] | null>(null);
  const [refundTarget, setRefundTarget] = useState<TxnWithOrder | null>(null);
  const [refundForm] = Form.useForm();
  const initiateRefund = useInitiateRefund();

  const { data, isLoading } = useAdminTransactions({
    page, limit: 20,
    q: search || undefined,
    status,
    from: dateRange?.[0],
    to: dateRange?.[1],
  });

  const onRefundSubmit = async (values: { amount: number; reason: string; type: "full" | "partial"; method: string }) => {
    if (!refundTarget?.order?.id) return;
    try {
      await initiateRefund.mutateAsync({
        orderId: refundTarget.order.id,
        amount: values.amount.toFixed(2),
        type: values.type,
        reason: values.reason,
        method: values.method,
      });
      void message.success(t("transactions.refundInitiated"));
      setRefundTarget(null);
      refundForm.resetFields();
    } catch {
      void message.error(t("transactions.refundFailed"));
    }
  };

  const columns: ColumnsType<TxnWithOrder> = [
    {
      title: t("transactions.colRef"), dataIndex: "reference", key: "ref", width: 180,
      render: (v) => <Text code style={{ fontSize: 12 }}>{v ?? "—"}</Text>,
    },
    {
      title: t("transactions.colOrder"), key: "order_code", width: 150,
      render: (_, row) => <Text style={{ fontSize: 12 }}>{row.order?.order_code ?? "—"}</Text>,
    },
    {
      title: t("transactions.colAmount"), dataIndex: "amount", key: "amount", width: 120,
      render: (v) => <Text strong>RM {v}</Text>,
      sorter: true,
    },
    {
      title: t("transactions.colMethod"), dataIndex: "method", key: "method", width: 110,
      render: (v) => v ? <Tag>{String(v).toUpperCase()}</Tag> : "—",
    },
    {
      title: t("transactions.colStatus"), dataIndex: "status", key: "status", width: 130,
      render: (v) => <StatusTag status={v} />,
    },
    {
      title: t("transactions.colPaidAt"), dataIndex: "paid_at", key: "paid_at", width: 160,
      render: (v) => v ? dayjs(v).format("DD MMM YYYY HH:mm") : "—",
    },
    {
      title: "", key: "actions", width: 100, fixed: "right",
      render: (_, row) => row.status === "success" ? (
        <Button size="small" danger onClick={() => {
          setRefundTarget(row);
          refundForm.setFieldsValue({ type: "full", amount: parseFloat(row.amount), method: row.method });
        }}>{t("transactions.refundBtn")}</Button>
      ) : null,
    },
  ];

  return (
    <AdminShell>
      <Title level={4} style={{ marginBottom: 16 }}>{t("transactions.title")}</Title>

      <Space wrap style={{ marginBottom: 16 }}>
        <Input prefix={<SearchOutlined />} placeholder={t("transactions.searchPlaceholder")} value={search}
          onChange={(e) => setSearch(e.target.value)} style={{ width: 220 }} allowClear />
        <Select placeholder={t("transactions.filterStatus")} allowClear value={status} onChange={setStatus} style={{ width: 160 }}
          options={[
            { value: "success", label: t("transactions.statusSuccess") },
            { value: "pending", label: t("transactions.statusPending") },
            { value: "refunded", label: t("transactions.statusRefunded") },
            { value: "failed", label: t("transactions.statusFailed") },
          ]} />
        <RangePicker onChange={(_, s) => setDateRange(s[0] && s[1] ? [s[0], s[1]] : null)} />
      </Space>

      <DataTable<TxnWithOrder>
        columns={columns}
        dataSource={data?.data as TxnWithOrder[] ?? []}
        loading={isLoading}
        pagination={{ current: page, total: data?.meta.total ?? 0, pageSize: 20, onChange: (p) => setPage(p) }}
      />

      {/* Initiate Refund Modal */}
      <Modal
        open={!!refundTarget}
        title={`${t("transactions.refundModalTitle")} — ${refundTarget?.order?.order_code ?? t("orders.colOrderId")}`}
        onCancel={() => { setRefundTarget(null); refundForm.resetFields(); }}
        onOk={() => void refundForm.submit()}
        okText={t("transactions.submitRefund")}
        okButtonProps={{ danger: true, loading: initiateRefund.isPending }}
      >
        <p style={{ marginBottom: 16, color: "#6B7280" }}>
          {t("transactions.refundOriginal")} <b>RM {refundTarget?.amount}</b> · {t("transactions.refundPaidVia")} <b>{refundTarget?.method?.toUpperCase()}</b>
        </p>
        <Form form={refundForm} layout="vertical" onFinish={onRefundSubmit}>
          <Form.Item name="type" label={t("transactions.refundType")} rules={[{ required: true }]}>
            <Select options={[
              { value: "full", label: t("transactions.refundTypeFull") },
              { value: "partial", label: t("transactions.refundTypePartial") },
            ]} />
          </Form.Item>
          <Form.Item name="amount" label={t("transactions.refundAmount")}
            rules={[{ required: true }, { type: "number", min: 0.01, max: parseFloat(refundTarget?.amount ?? "0") }]}>
            <InputNumber prefix="RM" min={0.01} max={parseFloat(refundTarget?.amount ?? "0")} precision={2} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="method" label={t("transactions.refundMethod")} rules={[{ required: true }]}>
            <Select options={REFUND_METHODS} />
          </Form.Item>
          <Form.Item name="reason" label={t("transactions.refundReason")} rules={[{ required: true, min: 3 }]}>
            <Input.TextArea rows={3} placeholder={t("transactions.refundReasonPlaceholder")} />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
