import { useState } from "react";
import { Input, Select, DatePicker, Button, Drawer, Descriptions, Typography, Space, Divider, Modal, Form, App } from "antd";
import { SearchOutlined, EyeOutlined, StopOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { Order, OrderItem } from "@kawkaw/shared";
import dayjs from "dayjs";
import { DataTable } from "../components/DataTable";
import { StatusTag } from "../components/StatusTag";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminOrders, useAdminOrder, useAdminCancelOrder } from "../api/hooks";

const { Title, Text } = Typography;
const { RangePicker } = DatePicker;

export function OrdersScreen() {
  const { t } = useTranslation();
  const { message } = App.useApp();
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState<string | undefined>();
  const [dateRange, setDateRange] = useState<[string, string] | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const { data, isLoading } = useAdminOrders({
    page,
    limit: 20,
    q: search || undefined,
    status,
    from: dateRange?.[0],
    to: dateRange?.[1],
  });

  const { data: orderDetail } = useAdminOrder(selectedId ?? "");
  const cancelOrder = useAdminCancelOrder();
  const [cancelTarget, setCancelTarget] = useState<Order | null>(null);
  const [cancelForm] = Form.useForm<{ reason: string }>();

  const TERMINAL = new Set(["cancelled", "completed", "delivered"]);
  const onCancel = async ({ reason }: { reason: string }) => {
    if (!cancelTarget) return;
    try {
      await cancelOrder.mutateAsync({ id: cancelTarget.id, reason });
      void message.success(t("orders.cancelSuccess", "Order cancelled"));
      setCancelTarget(null);
      cancelForm.resetFields();
    } catch {
      void message.error(t("orders.cancelFailed", "Failed to cancel order"));
    }
  };

  const columns: ColumnsType<Order> = [
    {
      title: t("orders.colOrderId"), dataIndex: "order_code", key: "order_code", width: 140,
      render: (v, row) => <Button type="link" onClick={() => setSelectedId(row.id)}>{v ?? row.id.slice(-8)}</Button>,
    },
    { title: t("orders.colCustomer"), dataIndex: ["customer", "name"], key: "customer", width: 140, render: (v) => v ?? "—" },
    {
      title: t("orders.colTotal"), dataIndex: "total", key: "total", width: 100,
      render: (v) => <Text strong>RM {v}</Text>,
    },
    {
      title: t("orders.colStatus"), dataIndex: "status", key: "status", width: 140,
      render: (v) => <StatusTag status={v} />,
      filters: [
        { text: t("orders.status.pending"), value: "pending" },
        { text: t("orders.status.confirmed"), value: "confirmed" },
        { text: t("orders.status.preparing"), value: "preparing" },
        { text: t("orders.status.ready"), value: "ready" },
        { text: t("orders.status.delivered"), value: "delivered" },
        { text: t("orders.status.completed"), value: "completed" },
        { text: t("orders.status.cancelled"), value: "cancelled" },
      ],
    },
    {
      title: t("orders.colPayment"), dataIndex: "payment_method", key: "payment_method", width: 100,
      render: (v) => v ?? "—",
    },
    {
      title: t("orders.colPlacedAt"), dataIndex: "created_at", key: "created_at", width: 160,
      render: (v) => dayjs(v).format("DD MMM YYYY HH:mm"),
      sorter: true,
    },
    {
      title: "", key: "actions", width: 110, fixed: "right",
      render: (_, row) => (
        <Space size={4}>
          <Button icon={<EyeOutlined />} size="small" onClick={() => setSelectedId(row.id)} />
          <Button
            icon={<StopOutlined />} size="small" danger
            disabled={TERMINAL.has(row.status)}
            onClick={() => { cancelForm.resetFields(); setCancelTarget(row); }}
            title={t("orders.cancelTooltip", "Cancel order")}
          />
        </Space>
      ),
    },
  ];

  return (
    <AdminShell>
      <Title level={4} style={{ marginBottom: 16 }}>{t("orders.title")}</Title>

      {/* Filters */}
      <Space wrap style={{ marginBottom: 16 }}>
        <Input
          prefix={<SearchOutlined />} placeholder={t("orders.searchPlaceholder")}
          value={search} onChange={(e) => setSearch(e.target.value)}
          style={{ width: 240 }} allowClear
        />
        <Select
          placeholder={t("orders.filterStatus")} allowClear value={status} onChange={setStatus}
          style={{ width: 160 }}
          options={[
            { value: "pending", label: t("orders.status.pending") },
            { value: "confirmed", label: t("orders.status.confirmed") },
            { value: "preparing", label: t("orders.status.preparing") },
            { value: "ready", label: t("orders.status.ready") },
            { value: "delivered", label: t("orders.status.delivered") },
            { value: "completed", label: t("orders.status.completed") },
            { value: "cancelled", label: t("orders.status.cancelled") },
          ]}
        />
        <RangePicker
          onChange={(_, strings) => setDateRange(strings[0] && strings[1] ? [strings[0], strings[1]] : null)}
        />
      </Space>

      <DataTable<Order>
        columns={columns}
        dataSource={data?.data ?? []}
        loading={isLoading}
        pagination={{
          current: page,
          total: data?.meta.total ?? 0,
          pageSize: 20,
          onChange: (p) => setPage(p),
        }}
      />

      {/* Order Detail Drawer */}
      <Drawer
        title={`${t("orders.colOrderId")} ${(orderDetail?.data as unknown as { order_code?: string })?.order_code ?? ""}`}
        open={!!selectedId}
        onClose={() => setSelectedId(null)}
        width={560}
      >
        {orderDetail?.data && (
          <>
            <Descriptions column={2} size="small" bordered>
              <Descriptions.Item label={t("orders.drawerStatus")} span={2}>
                <StatusTag status={orderDetail.data.status} />
              </Descriptions.Item>
              <Descriptions.Item label={t("orders.drawerCustomer")} span={2}>
                {(orderDetail.data as unknown as { customer?: { name: string } }).customer?.name ?? "—"}
              </Descriptions.Item>
              <Descriptions.Item label={t("orders.drawerPlaced")} span={2}>
                {dayjs(orderDetail.data.created_at).format("DD MMM YYYY, HH:mm")}
              </Descriptions.Item>
              <Descriptions.Item label={t("orders.drawerPayment")}>{(orderDetail.data as unknown as { payment_method?: string }).payment_method ?? "—"}</Descriptions.Item>
              <Descriptions.Item label={t("orders.colStatus")}>{orderDetail.data.type}</Descriptions.Item>
              {(() => {
                const note = (orderDetail.data as unknown as { special_note?: string | null }).special_note;
                return note ? <Descriptions.Item label={t("orders.drawerNotes")} span={2}>{note}</Descriptions.Item> : null;
              })()}
            </Descriptions>

            <Divider orientation="left" plain>{t("orders.drawerItems")}</Divider>
            {(orderDetail.data as unknown as { items?: OrderItem[] }).items?.map((item, i) => {
              const extrasTotal = item.options.reduce((s, o) => s + parseFloat(o.extra_charge), 0);
              const lineTotal = (parseFloat(item.price) + extrasTotal) * item.qty;
              return (
                <div key={i} style={{ padding: "6px 0", borderBottom: "1px solid #F3F4F6" }}>
                  <div style={{ display: "flex", justifyContent: "space-between" }}>
                    <Text>{item.name} × {item.qty}</Text>
                    <Text strong>RM {lineTotal.toFixed(2)}</Text>
                  </div>
                  {item.options.length > 0 && (
                    <div><Text type="secondary" style={{ fontSize: 12 }}>{item.options.map((o) => o.label).join(" | ")}</Text></div>
                  )}
                  {item.note && <div><Text type="secondary" style={{ fontSize: 12 }}>{item.note}</Text></div>}
                </div>
              );
            })}

            <Divider />
            <Descriptions column={1} size="small">
              <Descriptions.Item label={t("orders.drawerSubtotal")}>RM {orderDetail.data.subtotal}</Descriptions.Item>
              {parseFloat(orderDetail.data.voucher_discount) > 0 && (
                <Descriptions.Item label={t("orders.drawerDiscount")}>
                  <Text type="danger">- RM {orderDetail.data.voucher_discount}</Text>
                </Descriptions.Item>
              )}
              {parseFloat(orderDetail.data.sst_amount) > 0 && (
                <Descriptions.Item label={t("orders.drawerSST")}>RM {orderDetail.data.sst_amount}</Descriptions.Item>
              )}
              {parseFloat(orderDetail.data.delivery_fee) > 0 && (
                <Descriptions.Item label={t("orders.drawerDelivery")}>RM {orderDetail.data.delivery_fee}</Descriptions.Item>
              )}
              <Descriptions.Item label={t("orders.drawerTotal")}>
                <Text strong style={{ fontSize: 15 }}>RM {orderDetail.data.total}</Text>
              </Descriptions.Item>
            </Descriptions>
          </>
        )}
      </Drawer>

      <Modal
        open={!!cancelTarget}
        title={t("orders.cancelModalTitle", "Cancel order")}
        onCancel={() => { setCancelTarget(null); cancelForm.resetFields(); }}
        onOk={() => void cancelForm.submit()}
        okText={t("orders.cancelConfirm", "Cancel order")}
        okButtonProps={{ danger: true, loading: cancelOrder.isPending }}
        cancelText={t("common.back", "Back")}
      >
        <p style={{ color: "#6B7280", marginBottom: 12 }}>
          {t("orders.cancelHint", "This will mark the order as cancelled and notify the customer. Refunds (if any) must be issued separately from the Refunds screen.")}
        </p>
        <Form form={cancelForm} layout="vertical" onFinish={onCancel}>
          <Form.Item
            name="reason"
            label={t("orders.cancelReason", "Reason (visible in activity log)")}
            rules={[{ required: true, min: 3, max: 500 }]}
          >
            <Input.TextArea rows={3} maxLength={500} showCount placeholder={t("orders.cancelReasonPlaceholder", "e.g. duplicate order, customer requested cancellation, ingredient shortage…")} />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
