import { useState } from "react";
import {
  Button, Modal, Form, Input, InputNumber, Select,
  DatePicker, Space, Typography, message, Tag, Popconfirm,
} from "antd";
import { PlusOutlined, EditOutlined, DeleteOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import type { ColumnsType } from "antd/es/table";
import type { Voucher } from "@kawkaw/shared";
import dayjs from "dayjs";
import { DataTable } from "../components/DataTable";
import { StatusTag } from "../components/StatusTag";
import { AdminShell } from "../layouts/AdminShell";
import { useAdminVouchers, useCreateVoucher, useUpdateVoucher, useDeleteVoucher } from "../api/hooks";

const { Title } = Typography;

export function VouchersScreen() {
  const { t } = useTranslation();
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Voucher | null>(null);
  const [form] = Form.useForm();

  const { data, isLoading } = useAdminVouchers();
  const createVoucher = useCreateVoucher();
  const updateVoucher = useUpdateVoucher();
  const deleteVoucher = useDeleteVoucher();

  const openCreate = () => { setEditing(null); form.resetFields(); setModalOpen(true); };
  const openEdit = (v: Voucher) => {
    setEditing(v);
    // Map canonical → form field names. Backend uses `type / value / min_order /
    // total_uses / valid_to`; the form uses the older names below for legacy
    // i18n keys. The hook maps them back on save.
    form.setFieldsValue({
      ...v,
      discount_type: v.type,
      discount_value: v.value,
      min_spend: v.min_order,
      usage_limit: v.total_uses,
      valid_from: v.valid_from ? dayjs(v.valid_from) : null,
      valid_until: v.valid_to ? dayjs(v.valid_to) : null,
    });
    setModalOpen(true);
  };

  const onSave = async (values: Record<string, unknown>) => {
    const payload = {
      ...values,
      valid_from: (values.valid_from as dayjs.Dayjs | undefined)?.toISOString() ?? null,
      valid_until: (values.valid_until as dayjs.Dayjs | undefined)?.toISOString() ?? null,
    };
    try {
      if (editing) {
        await updateVoucher.mutateAsync({ id: editing.id, ...payload });
        void message.success(t("vouchers.updateSuccess"));
      } else {
        await createVoucher.mutateAsync(payload);
        void message.success(t("vouchers.createSuccess"));
      }
      setModalOpen(false);
    } catch {
      void message.error(t("vouchers.saveFailed"));
    }
  };

  const columns: ColumnsType<Voucher> = [
    { title: t("vouchers.colCode"), dataIndex: "code", key: "code", render: (v) => <Tag style={{ fontFamily: "monospace" }}>{v}</Tag> },
    {
      title: t("vouchers.colType"), dataIndex: "type", key: "type", width: 120,
      render: (v) => <Tag>{String(v).replace(/_/g, " ")}</Tag>,
    },
    {
      title: t("vouchers.colValue"), key: "value", width: 110,
      render: (_, row) => row.type === "percentage"
        ? `${row.value}%`
        : `RM ${row.value}`,
    },
    {
      title: t("vouchers.colMinSpend"), dataIndex: "min_order", key: "min", width: 110,
      render: (v) => v && Number(v) > 0 ? `RM ${v}` : "—",
    },
    {
      title: t("vouchers.colUses"), key: "uses", width: 100,
      render: (_, row) => `${row.used_count ?? 0} / ${row.total_uses ?? "∞"}`,
    },
    {
      title: t("vouchers.colStatus"), dataIndex: "status", key: "status", width: 110,
      render: (v) => <StatusTag status={v} />,
    },
    {
      title: t("vouchers.colValidUntil"), dataIndex: "valid_to", key: "until", width: 140,
      render: (v) => v ? dayjs(v).format("DD MMM YYYY") : "—",
    },
    {
      title: "", key: "actions", width: 110, fixed: "right",
      render: (_, row) => (
        <Space size={4}>
          <Button size="small" icon={<EditOutlined />} onClick={() => openEdit(row)} />
          <Popconfirm
            title={t("vouchers.deleteConfirm", "Disable this voucher?")}
            description={t("vouchers.deleteConfirmDesc", "It will be marked disabled and unusable.")}
            okText={t("common.yes", "Yes")}
            cancelText={t("common.no", "No")}
            onConfirm={async () => {
              try {
                await deleteVoucher.mutateAsync(row.id);
                void message.success(t("vouchers.deleteSuccess", "Voucher disabled"));
              } catch {
                void message.error(t("vouchers.deleteFailed", "Failed to disable voucher"));
              }
            }}
          >
            <Button size="small" danger icon={<DeleteOutlined />} disabled={row.status === "disabled"} />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <AdminShell>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <Title level={4} style={{ margin: 0 }}>{t("vouchers.title")}</Title>
        <Button type="primary" icon={<PlusOutlined />} onClick={openCreate}
          style={{ background: "#D97706", borderColor: "#D97706" }}>
          {t("vouchers.newVoucher")}
        </Button>
      </div>

      <DataTable<Voucher> columns={columns} dataSource={(data?.data ?? []) as unknown as Voucher[]} loading={isLoading} />

      <Modal
        open={modalOpen}
        title={editing ? t("vouchers.editTitle") : t("vouchers.newTitle")}
        onCancel={() => setModalOpen(false)}
        onOk={() => void form.submit()}
        okButtonProps={{ style: { background: "#D97706", borderColor: "#D97706" }, loading: createVoucher.isPending || updateVoucher.isPending }}
        width={520}
        maskClosable={false}
      >
        <Form form={form} layout="vertical" onFinish={onSave}>
          <Form.Item name="code" label={t("vouchers.formCode")} rules={[{ required: true }]}>
            <Input
              style={{ fontFamily: "monospace", textTransform: "uppercase" }}
              onChange={(e) => form.setFieldValue("code", e.target.value.toUpperCase())}
            />
          </Form.Item>
          <Form.Item name="discount_type" label={t("vouchers.formDiscountType")} rules={[{ required: true }]}>
            <Select
              options={[
                { value: "percentage", label: t("vouchers.formDiscountTypePercentage") },
                { value: "fixed", label: t("vouchers.formDiscountTypeFixed") },
                { value: "free_item", label: t("vouchers.formDiscountTypeFreeItem") },
              ]}
              getPopupContainer={(node) => node.parentElement ?? document.body}
            />
          </Form.Item>
          <Form.Item name="discount_value" label={t("vouchers.formDiscountValue")} rules={[{ required: true }]}>
            <InputNumber min={0} precision={2} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="min_spend" label={t("vouchers.formMinSpend")}>
            <InputNumber min={0} precision={2} style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item name="usage_limit" label={t("vouchers.formUsageLimit")}>
            <InputNumber min={1} style={{ width: "100%" }} />
          </Form.Item>
          <Space style={{ width: "100%" }} direction="vertical">
            <Form.Item name="valid_from" label={t("vouchers.formValidFrom")}>
              <DatePicker showTime style={{ width: "100%" }} />
            </Form.Item>
            <Form.Item name="valid_until" label={t("vouchers.formValidUntil")}>
              <DatePicker showTime style={{ width: "100%" }} />
            </Form.Item>
          </Space>
          <Form.Item name="status" label={t("vouchers.formStatus")} initialValue="active">
            <Select
              options={[
                { value: "active", label: t("vouchers.formStatusActive") },
                { value: "scheduled", label: t("vouchers.formStatusScheduled") },
                { value: "expired", label: t("vouchers.formStatusExpired") },
                { value: "disabled", label: t("vouchers.formStatusDisabled") },
              ]}
              getPopupContainer={(node) => node.parentElement ?? document.body}
            />
          </Form.Item>
        </Form>
      </Modal>
    </AdminShell>
  );
}
